/* Year 12 explicit relativity journeys: authored original exam-style practice. */
(function(){'use strict';
const C=window.PhysicsScenarioCourse,{esc,math,note,pair,steps,paper,reveal,svg,text,line,arrow,ball,check,number}=C.helpers;
const P=s=>'<p>'+s+'</p>',E=math,gamma=b=>1/Math.sqrt(1-b*b);
const marking=ps=>'<table class="pf-marking"><thead><tr><th>Expected reasoning and working</th><th>Marks</th></tr></thead><tbody>'+ps.map(p=>'<tr><td>'+esc(p)+'</td><td>1</td></tr>').join('')+'</tbody></table>';
const rect=(x,y,w,h,label,color='#d4e8f4')=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="8" fill="'+color+'" stroke="#2a6bb2"/>'+text(x+w/2,y+h/2+7,label,'#18374d','middle');
function frames(){return svg('Earth frame S and train frame S prime with signed velocities',arrow(65,290,695,290)+text(90,330,'Earth frame S: +x right')+rect(240,130,290,90,'')+text(275,155,'Train frame S′')+arrow(250,90,450,90)+text(240,65,'Train moves at +v in S')+ball(380,190,12)+arrow(400,190,475,190,'#c87518')+text(85,375,'Passenger velocity is measured relative to a stated frame.'),410);}
function eventMap(){return svg('Two events have labelled positions and clock readings in one frame',arrow(90,320,685,320)+text(100,370,'Position x (m) in frame S')+ball(180,240,15)+ball(560,130,15,'#2a6bb2')+text(115,195,'Event A: x = 0 m')+text(115,225,'t = 0 s')+text(430,75,'Event B: x = 600 m')+text(430,105,'t = 2 μs')+line(180,245,180,320,'#94aebd',true)+line(560,145,560,320,'#94aebd',true)+text(85,420,'Positions and times are measurements, not arrival times of images.'),460);}
function synchronise(){return svg('Einstein clock synchronisation uses a round-trip light pulse',rect(85,135,120,90,'Clock A')+rect(550,135,120,90,'Clock B')+arrow(220,155,535,155,'#c87518')+arrow(535,205,220,205,'#0b8774')+text(270,120,'outgoing pulse')+text(270,250,'reflected pulse')+text(85,320,'A sends at t₁; A receives at t₃.')+text(85,375,'Assign reflection time at B: t₂ = (t₁ + t₃)/2.'),420);}
function train(){return svg('Simultaneous flashes in platform frame; train observer moves toward front flash',line(75,300,700,300)+ball(120,190,13,'#c87518')+ball(640,190,13,'#c87518')+rect(270,205,200,60,'moving observer')+arrow(370,185,465,185,'#2a6bb2')+arrow(140,155,340,155)+arrow(620,155,400,155)+text(85,80,'Platform frame: rear and front emit at equal t')+text(75,340,'Rear')+text(615,340,'Front')+text(75,395,'Reception order differs; simultaneity needs frame coordinates.'),430);}
function lightClock(){return svg('Light clock path vertical at rest and diagonal in another frame',rect(90,90,140,240,'')+ball(160,280,10)+arrow(160,270,160,125,'#c87518')+text(70,365,'Clock rest frame')+rect(380,90,140,240,'')+rect(510,90,140,240,'')+arrow(450,280,580,125,'#2a6bb2')+text(380,365,'Observer sees diagonal path')+text(70,55,'Same vacuum light speed c; longer path means longer interval.'),410);}
function gammaPlot(){let b=arrow(90,320,685,320)+arrow(90,320,90,55,'#2a6bb2'),d='';for(let i=0;i<=95;i++){const x=i/100;d+=(i?'L':'M')+(90+x*600)+' '+(320-(gamma(x)-1)*85);}b+='<path d="'+d+'" fill="none" stroke="#c87518" stroke-width="4"/>';for(let x of [0,.2,.4,.6,.8])b+=text(90+x*600,350,x.toFixed(1),'#18374d','middle');for(let g of [1,2,3])b+=text(70,320-(g-1)*85,String(g),'#18374d','end');return svg('Lorentz factor gamma versus speed fraction beta, rapidly rising near c',b+text(260,390,'β = v/c')+text(105,40,'γ = 1/√(1 − β²)')+text(90,435,'Shown 0 ≤ β ≤ 0.95; γ diverges as β tends to 1.'),470);}
function velocityScene(){return svg('Earth-frame approaching spacecraft versus a transformed relative velocity',arrow(60,320,695,320)+rect(100,150,140,80,'A: +0.6c')+rect(515,150,140,80,'B: −0.6c')+arrow(240,190,350,190)+arrow(515,190,405,190,'#2a6bb2')+text(90,70,'In Earth frame: separation shrinks at 1.2c')+text(90,275,'In A frame: B has velocity −0.882c')+text(90,375,'Closing rate in one frame is not a local relative speed.'),410);}
function clockPair(){return svg('Two ticks occur at one location in clock rest frame; moving-frame interval is longer',rect(85,90,240,110,'Clock rest frame')+rect(430,90,240,110,'Observer frame')+text(115,255,'Two ticks: Δτ = 3.00 s')+text(450,255,'At 0.8c: Δt = 5.00 s')+text(90,330,'Proper time is measured by the clock at both events.')+text(90,385,'The intervals compare the same two tick events.'),420);}
function delay(){return svg('Separate clock emission times from light arrival times',rect(90,100,150,90,'Emitter')+rect(540,100,150,90,'Receiver')+arrow(250,135,530,135,'#c87518')+text(285,110,'light travel')+text(80,255,'Emission time is a coordinate event.')+text(80,315,'Arrival time adds propagation delay.')+text(80,375,'Changing distance can alter arrival spacing independently.'),420);}
function rod(){return svg('Proper rod length compared with contracted parallel length at speed 0.8c',rect(90,105,540,50,'Rest length L₀ = 10.0 m')+rect(90,235,324,50,'Moving length L = 6.00 m')+arrow(435,260,585,260)+text(90,55,'Measure both endpoints at the same time in your frame')+text(90,340,'Only the dimension parallel to relative motion contracts.')+text(90,390,'This diagram compares measurements, not a crushed object.'),425);}
function direction(){return svg('A moving rectangle contracts along x but not along y',rect(100,110,220,180,'Rest object')+rect(440,110,132,180,'Moving')+arrow(435,65,610,65)+text(70,335,'For β = 0.8: x dimension ×0.6; y dimension unchanged')+text(70,395,'Motion right; endpoints simultaneous in each measuring frame.'),440);}
function muons(){return svg('Muon flight compared in Earth and muon frames',rect(65,90,280,100,'Earth: atmosphere at rest')+rect(415,90,280,100,'Muon: atmosphere moving')+arrow(185,220,185,320,'#c87518')+arrow(540,320,540,220,'#2a6bb2')+text(85,240,'Muon travels distance L₀')+text(435,240,'Ground approaches')+text(85,375,'Earth: longer lifetime γτ₀')+text(415,375,'Muon: shorter layer L₀/γ'),420);}
function twins(){return svg('Twin round trip: Earth worldline and two cruise legs meeting again',arrow(130,360,130,60,'#2a6bb2')+arrow(130,360,650,360)+line(150,340,150,85,'#0b8774')+line(150,340,465,210,'#c87518')+line(465,210,150,85,'#c87518')+ball(150,340)+ball(150,85)+text(490,215,'turnaround')+text(170,320,'departure')+text(170,80,'reunion')+text(195,400,'Earth position x')+text(35,45,'Earth time t')+text(65,450,'Schematic worldlines; traveller changes inertial frame.'),485);}
function momentumPlot(){let b=arrow(90,320,685,320)+arrow(90,320,90,50,'#2a6bb2'),d='';for(let i=0;i<=95;i++){let x=i/100;d+=(i?'L':'M')+(90+x*600)+' '+(320-gamma(x)*x*85);}b+='<path d="'+d+'" fill="none" stroke="#c87518" stroke-width="4"/>'+line(90,320,660,239.25,'#0b8774',true)+text(100,40,'p/(mc)')+text(265,390,'β = v/c')+text(95,430,'Orange: γβ; dashed green: classical β');for(let x of [0,.2,.4,.6,.8])b+=text(90+x*600,350,x.toFixed(1),'#18374d','middle');for(let y of [0,1,2,3])b+=text(70,325-y*85,String(y),'#18374d','end');return svg('Relativistic momentum rises above classical momentum at high speed',b,470);}
function energy(){return svg('Rest, kinetic and total energy for gamma equal to two',rect(80,130,250,60,'Rest: mc²','#d4e8f4')+rect(330,130,250,60,'Kinetic: mc²','#e9f4de')+line(80,220,580,220)+text(140,270,'Total: E = 2mc²')+text(80,55,'Example γ = 2: total energy is rest plus kinetic')+text(80,350,'Invariant mass m remains unchanged.'),400);}
function invariant(){return svg('Energy momentum relationship as a right triangle of energy quantities',line(100,330,620,330)+line(620,330,620,120)+line(100,330,620,120,'#c87518')+text(330,370,'pc')+text(640,240,'mc²')+text(265,165,'E')+text(95,55,'E² = (pc)² + (mc²)²')+text(95,430,'All side labels are energies. Schematic, not a physical path.'),470);}
function annihilation(){return svg('Electron positron annihilation at rest: two opposite photons conserve momentum',ball(290,180,25,'#2a6bb2')+ball(405,180,25,'#c87518')+text(275,187,'e⁻')+text(390,187,'e⁺')+arrow(260,255,100,255)+arrow(435,255,650,255)+text(100,305,'photon: 0.511 MeV')+text(430,305,'photon: 0.511 MeV')+text(75,55,'Centre-of-mass frame: initial total momentum zero')+text(75,375,'Opposite photon momenta add to zero; energies add.'),420);}
function massSystem(){return svg('A closed box with contained energy contributes to its invariant mass',rect(220,100,300,180,'')+text(270,125,'Closed box')+arrow(250,235,485,135,'#c87518')+arrow(485,235,250,135,'#c87518')+text(70,55,'Contained photons or thermal energy remain in the system')+text(70,345,'Added rest-frame energy ΔE gives system mass increase ΔE/c².')+text(70,395,'A photon has zero invariant mass; a photon system need not.'),440);}
function elevator(){return svg('Local equivalence: supported lab in gravity and accelerating rocket',rect(70,100,250,230,'')+rect(435,100,250,230,'')+ball(195,240,18)+ball(560,240,18)+arrow(195,220,195,145,'#0b8774')+arrow(560,220,560,145,'#0b8774')+text(90,70,'Lab supported in gravity')+text(445,70,'Rocket accelerating up')+text(90,360,'Floor pushes observer up')+text(445,360,'Floor pushes observer up')+text(65,420,'Locally similar support forces; global tidal effects can differ.'),465);}
function freefall(){return svg('Free falling lab: observer and released object fall together',rect(230,95,300,220,'')+ball(315,190,18)+ball(435,190,10,'#2a6bb2')+arrow(315,220,315,295)+arrow(435,220,435,295)+text(85,50,'Ideal local free fall: no floor support force')+text(85,370,'Both accelerate together in Earth coordinates.')+text(85,420,'Locally weightless does not mean gravity has vanished.'),460);}
function curvature(){let b=text(65,45,'Mass-energy changes spacetime geometry');for(let i=0;i<6;i++){let y=100+i*45;b+='<path d="M70 '+y+' Q380 '+(y+85*Math.sin(i/5*Math.PI))+' 690 '+y+'" stroke="#9aaebc" fill="none" stroke-width="2"/>';}b+=ball(380,235,45,'#c87518')+'<path d="M70 100 Q280 100 400 140 T690 180" stroke="#0b8774" stroke-width="4" fill="none"/>'+text(65,395,'Grid is an analogy; spacetime has three space dimensions and time.')+text(65,440,'Free-fall paths follow geometry without needing a supporting surface.');return svg('Schematic curved geometry and a free-fall path; grid is a limited analogy',b,480);}
function tidal(){return svg('Gravity gradient produces tidal relative acceleration in an extended lab',ball(380,330,55,'#c87518')+ball(330,100,12,'#2a6bb2')+ball(430,100,12,'#2a6bb2')+arrow(330,120,352,235)+arrow(430,120,408,235)+text(65,50,'Separated falling particles can approach or separate')+text(65,420,'Tidal differences distinguish an extended gravitational field.')+text(65,460,'A small local equivalence experiment neglects these differences.'),500);}
function gps(){return svg('GPS clock corrections: gravitational gain and speed related loss relative to ground',rect(65,115,285,100,'Higher satellite clock')+rect(420,115,285,100,'Ground reference')+arrow(65,290,455,290,'#0b8774')+text(70,265,'Example GR: +45 μs/day')+arrow(65,340,125,340,'#c87518')+text(155,347,'Example SR: −7 μs/day')+text(65,410,'Example net: +38 μs/day before correction.')+text(65,455,'Supplied approximate data; not a universal orbit value.'),495);}
function redshift(){return svg('Light emitted from lower gravitational potential is redshifted at a higher receiver',rect(250,290,260,60,'Lower emitter')+rect(250,85,260,60,'Higher receiver')+arrow(380,280,380,155,'#c87518')+text(65,40,'Compare frequency using local stationary clocks')+text(65,410,'Higher receiver measures lower frequency for upward light.')+text(65,455,'Diagram is qualitative; no core GR frequency formula assumed.'),495);}
function lens(){return svg('Gravitational lens: bent light paths can form multiple images of one source',ball(90,210,16,'#2a6bb2')+ball(380,210,40,'#c87518')+ball(670,210,12,'#0b8774')+'<path d="M90 210 Q380 40 670 210 M90 210 Q380 380 670 210" stroke="#2a6bb2" stroke-width="3" fill="none"/>'+text(60,145,'source')+text(335,285,'lens mass')+text(610,145,'observer')+text(65,50,'Schematic: different light paths from one background source')+text(65,410,'Images need not be duplicate physical objects.'),450);}
function horizon(){return svg('Black hole horizon is a causal boundary, distinct from surrounding emission','<circle cx="380" cy="210" r="95" fill="#173348"/><ellipse cx="380" cy="210" rx="190" ry="65" fill="none" stroke="#c87518" stroke-width="20"/>'+text(65,50,'Not to scale; schematic horizon and outside emitting material')+line(447,143,625,95)+text(535,75,'horizon boundary')+line(205,245,90,315)+text(65,350,'outside hot material')+text(65,420,'Light from outside can reach us; no outgoing light from inside.'),460);}
function waves(){let b=arrow(80,265,690,265)+arrow(80,265,80,65,'#2a6bb2'),d='';for(let i=0;i<=180;i++){let t=i/180,x=85+t*590,amp=20+85*t*t,y=220+amp*Math.sin(2*Math.PI*(3*t+8*t*t));d+=(i?'L':'M')+x+' '+y;}b+='<path d="'+d+'" fill="none" stroke="#c87518" stroke-width="3"/>'+text(95,40,'Schematic strain signal: amplitude and frequency rise')+text(280,370,'detector time')+text(90,420,'Illustrative chirp, not a recorded event or quantitative waveform.');return svg('Qualitative gravitational-wave chirp from an approaching merger',b,460);}
const figs={frames,eventMap,synchronise,train,lightClock,gammaPlot,velocityScene,clockPair,delay,rod,direction,muons,twins,momentumPlot,energy,invariant,annihilation,massSystem,elevator,freefall,curvature,tidal,gps,redshift,lens,horizon,waves};
function explore(kind){return '<div class="pp-sim" data-rel-explore="'+kind+'"><label>Speed fraction β = v/c <input type="range" min="0" max="0.99" step="0.01" value="0.6"><output></output></label><div data-rel-scene></div><p data-rel-result aria-live="polite"></p><p>Predict which quantities change before moving the slider. Invariant mass remains fixed.</p></div>';}
function wireRel(root){root.querySelectorAll('[data-rel-explore]').forEach(box=>{const input=box.querySelector('input'),kind=box.dataset.relExplore;const update=()=>{let b=Number(input.value),g=gamma(b);box.querySelector('output').textContent=b.toFixed(2);let body=text(65,55,'Calculated model: β = '+b.toFixed(2)+'; γ = '+g.toFixed(4));if(kind==='energy')body+=text(80,135,'Rest energy / mc² = 1')+text(80,205,'Total energy / mc² = '+g.toFixed(4))+text(80,275,'Kinetic energy / mc² = '+(g-1).toFixed(4))+text(80,345,'Momentum / mc = '+(g*b).toFixed(4));else body+=text(80,135,'Moving-clock interval / proper interval = '+g.toFixed(4))+rect(90,200,500/g,50,'L/L₀ = '+(1/g).toFixed(4))+text(80,330,'Parallel length contracts; transverse length unchanged.');box.querySelector('[data-rel-scene]').innerHTML=svg('Interactive Lorentz factor and '+kind+' ratios',body);box.querySelector('[data-rel-result]').textContent=b===0?'At rest γ = 1.':b<.1?'At low speed relativistic ratios are close to their classical values.':'As speed increases, gamma rises. The changing measured quantities do not imply a change of invariant mass.';};input.addEventListener('input',update);update();});}
const specs=[{"id": "relativity-foundations-focus-1", "parent": "relativity-foundations", "title": "Reference frames: events, velocities and operational measurements", "shortTitle": "Frames & events", "subtitle": "Identify inertial frames, label events operationally and solve signed low-speed relative-motion and signal-delay cases.", "rows": [{"chapter": 0, "title": "Whose measurement are we using?", "body": "A passenger can be at rest relative to a train while moving relative to the platform. Neither description is incomplete once the frame is named. Every position, velocity and time coordinate must identify its reference frame.", "fig": "frames", "type": "learn"}, {"chapter": 0, "title": "What makes a frame?", "body": "A frame is a system of position coordinates and synchronised clocks used to label events. It is more than one person’s eyesight. A frame can correct for the travel time of light signals before assigning an event time.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "An event is something at a place and time", "body": "A lamp flashes at a particular position and moment. The flash event has coordinates x and t in one frame and generally different x′ and t′ in another. The two coordinate descriptions refer to the same physical event.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Inertial means no acceleration", "body": "An inertial frame moves at constant velocity relative to another inertial frame in a region where gravitational effects can be neglected. A turning car, braking train or accelerating rocket is not inertial over that manoeuvre.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Choose axes before signs", "body": "Let right be positive in both aligned frames. Train velocity +20 m/s, passenger forward velocity +2 m/s relative to train and passenger backward velocity −2 m/s are signed quantities. Speed alone omits the direction.", "fig": "eventMap", "type": "learn"}, {"chapter": 0, "title": "Coordinate time versus image arrival", "body": "Seeing a distant flash later does not mean it occurred later. A coordinate measurement corrects propagation delay using the frame’s distance and signal model. Distinguish event occurrence, signal emission and signal reception.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "A simple classical approximation", "body": "At ordinary speeds, platform velocity of a passenger is approximately train velocity plus passenger velocity relative to train. This is a low-speed approximation; it will not correctly combine near-light-speed velocities.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Define the three velocities", "body": "Let S be the platform frame and S′ the train frame. S′ moves at v relative to S; an object has u′ in S′ and u in S. Classical u ≈ u′ + v applies when all relevant speeds are much smaller than c.", "fig": "synchronise", "type": "learn"}, {"chapter": 1, "title": "Describe zero velocity properly", "body": "If u′ = 0, the object is at rest in S′ and has u = v in S. At rest is always a frame-dependent statement. Zero velocity in one frame does not mean a universal absolute state of rest.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Relative position needs an origin", "body": "At t = 0 aligned origins meet. In a low-speed model x′ = x − vt. A passenger coordinate can stay fixed in the train while the platform coordinate increases. Specify initial origin offsets if they are not zero.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "A clock network measures an interval", "body": "To measure travel between distant positions in S, use clocks synchronised in S. A single travelling clock can instead record its own elapsed proper time. These are different measurement arrangements, especially at relativistic speed.", "fig": "frames", "type": "learn"}, {"chapter": 1, "title": "One frame’s separation rate", "body": "If A and B have coordinates x_A and x_B in S, separation is x_B − x_A and its rate is u_B − u_A. This coordinate rate is not automatically the velocity either object measures in its own rest frame at high speed.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "No hidden preferred frame", "body": "Special relativity does not choose the platform as the true stationary frame. The laws of physics have the same form in all inertial frames. We choose the platform because it suits the question, not because it is absolute.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Use a frame table, not a slogan", "body": "For each given quantity write the object, measuring frame, sign and unit. This prevents adding a velocity measured in one frame to an unrelated quantity measured in another without a transformation.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: passenger walking forward", "body": "A train moves right at 18.0 m/s relative to the platform. A passenger walks right at 1.50 m/s relative to the train. At these low speeds use u ≈ v + u′.", "fig": "eventMap", "type": "worked"}, {"chapter": 2, "title": "Worked: platform measurement", "body": "u ≈ 18.0 + 1.50 = +19.5 m/s. The positive sign means right in the platform frame. In the passenger’s own rest frame the passenger velocity is zero; these answers describe different measurements.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: passenger walking backward", "body": "If the same passenger walks left at 1.50 m/s relative to the train, u′ = −1.50 m/s. Then u ≈ 18.0 − 1.50 = +16.5 m/s. Walking backward in the train does not necessarily mean moving left relative to the platform.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: two cars approaching", "body": "In a road frame, A moves right at +12.0 m/s and B left at −8.00 m/s. Let B initially be 100 m to A’s right. Separation shrinks at 20.0 m/s under constant-speed motion.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: time to meet", "body": "Meeting time = 100/(12.0 + 8.00) = 5.00 s. A travels 60.0 m and B 40.0 m toward the meeting point. This coordinate closing-rate method is valid in the named road frame.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: overtaking instead", "body": "A moves right at 20.0 m/s and B right at 15.0 m/s, with A initially 50.0 m behind. Separation shrinks at 20.0 − 15.0 = 5.00 m/s, so meeting takes 10.0 s. Adding the speeds would model a different geometry.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: correct a delayed flash", "body": "A lamp is 600 m away in S. With c = 3.00 × 10⁸ m/s, light takes 600/c = 2.00 μs to arrive. If reception is at t = 10.0 μs, emission was at t = 8.00 μs in S under this fixed-distance model.", "fig": "synchronise", "type": "worked"}, {"chapter": 2, "title": "Worked: synchronise by reflection", "body": "Clock A sends a pulse at 2.00 μs and receives its reflection at 10.0 μs. Under the inertial equal-outbound/return convention, reflection at B is assigned (2.00 + 10.0)/2 = 6.00 μs.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: find the clock separation", "body": "One-way travel time is 4.00 μs, so separation = c × 4.00 × 10⁻⁶ = 1200 m. The clocks are at rest in the same frame for this model. A moving reflector would require different bookkeeping.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: identify a non-inertial interval", "body": "A train maintains speed through a straight section, then brakes. The straight constant-velocity section can be approximated as inertial; the braking interval cannot. One frame label should not hide a changing velocity.", "fig": null, "type": "worked"}], "guides": [{"q": "Train +25 m/s; passenger −2 m/s in train. Low-speed platform velocity?", "value": 23, "unit": "m/s", "why": "u ≈ 25 − 2 = +23 m/s.", "tolerance": 0.025}, {"q": "A fixed lamp is 900 m away. Vacuum signal travel time?", "value": 3, "unit": "μs", "why": "900/(3.00×10⁸) = 3.00×10⁻⁶ s = 3.00 μs.", "tolerance": 0.025}], "practice": [{"q": "A train moves +16.0 m/s relative to a platform. A passenger walks −2.00 m/s relative to the train. Find platform velocity and explain why the passenger can still move right in the platform frame.", "points": ["State right-positive and identify both frames.", "u ≈ v + u′ = 16.0 − 2.00.", "u = +14.0 m/s.", "Backward relative to the train is slower than the train’s forward motion."]}, {"q": "A stationary clock receives a pulse from a fixed lamp 1500 m away at t = 12.0 μs. Find emission time using c = 3.00×10⁸ m/s and distinguish event time from reception time.", "points": ["Propagation time = 1500/c = 5.00 μs.", "Emission time = 12.0 − 5.00 = 7.00 μs.", "Reception is a separate event at the clock.", "The calculation assumes fixed separation and vacuum light travel in one inertial frame."]}], "tasks": [{"q": "Two low-speed cars in a road frame approach with velocities +14.0 and −6.00 m/s, initially 160 m apart. Find meeting time and each distance.", "points": ["Closing rate = 20.0 m/s.", "Meeting time = 160/20 = 8.00 s.", "First distance = 112 m.", "Second distance = 48.0 m; distances sum to 160 m."]}, {"q": "An inertial reflection test sends light at 1.00 μs and receives it at 9.00 μs. Assign reflection time and separation of fixed clocks.", "points": ["Reflection time = (1 + 9)/2 = 5.00 μs.", "One-way time = 4.00 μs.", "Separation = c×4.00×10⁻⁶ = 1200 m.", "Both clocks are at rest in the same frame with the stated synchronisation convention."]}], "bank": [{"q": "A frame assigns an event…", "o": ["position and time coordinates", "only an image brightness", "an absolute rest label"], "a": 0, "explain": "A coordinate system and synchronised clocks label events."}, {"q": "A braking train frame is…", "o": ["inertial throughout", "accelerating during braking", "always the preferred frame"], "a": 1, "explain": "Its velocity changes during braking."}, {"q": "At rest means…", "o": ["zero velocity in a specified frame", "no velocity in every frame", "no mass"], "a": 0, "explain": "Rest depends on the chosen frame."}, {"q": "Reception later necessarily means emission later?", "o": ["Yes", "No, travel delays matter", "Only for clocks"], "a": 1, "explain": "Occurrence and arrival are separate events."}, {"q": "For ordinary speeds u ≈…", "o": ["u′+v", "u′v", "c always"], "a": 0, "explain": "Classical velocity addition is the low-speed approximation."}, {"q": "Overtaking in one direction uses a closing rate…", "o": ["sum of positive speeds", "difference of speeds", "zero always"], "a": 1, "explain": "The faster object gains on the slower at the speed difference."}], "transfer": [["A frame-specific operational check", "Ask which clock records each event and how clocks at different locations were synchronised. A statement about what an observer sees is not automatically a statement about coordinate simultaneity."], ["A high-speed warning", "If both spacecraft move near c, still calculate coordinate separation rate within one frame when that is asked. To find the velocity measured aboard one spacecraft, use the relativistic transformation instead."], ["A round-trip signal caveat", "The midpoint reflection-time convention applies to stationary endpoints in the specified inertial frame. A moving endpoint changes the travel geometry; do not reuse the same distance formula blindly."]], "summary": "Identify inertial frames, label events operationally and solve signed low-speed relative-motion and signal-delay cases.", "mode": null}, {"id": "relativity-foundations-focus-2", "parent": "relativity-foundations", "title": "Einstein’s postulates: light clocks and simultaneity", "shortTitle": "Postulates & simultaneity", "subtitle": "Explain the two postulates, operational simultaneity and why moving light clocks have longer coordinate intervals.", "rows": [{"chapter": 0, "title": "Why does classical addition fail for light?", "body": "A train rider and platform observer can disagree about train velocity, but both inertial frames measure vacuum light speed c. Adding train speed to c would contradict this result. The classical assumptions about time must change.", "fig": "train", "type": "learn"}, {"chapter": 0, "title": "The first postulate", "body": "The laws of physics have the same form in every inertial frame. A closed constant-velocity laboratory cannot identify an absolute state of rest by its internal laws. Acceleration can be detected and is a different situation.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The second postulate", "body": "Vacuum light speed c is the same for all inertial observers, independent of the source’s constant velocity. This concerns locally measured vacuum speed. Light in glass or water is a different material-propagation problem.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "A frame is more than eyesight", "body": "Observers correct for light travel when assigning event coordinates. Seeing two flashes at different times does not by itself prove they were emitted at different coordinate times. Measurement procedures matter.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "A clock is a repeatable process", "body": "An ideal light clock uses a pulse travelling between mirrors. In its rest frame the mirror separation is fixed and the pulse follows a vertical path. One round trip is one tick interval in the model.", "fig": "lightClock", "type": "learn"}, {"chapter": 0, "title": "Moving light clock has a diagonal path", "body": "In another frame the mirrors move horizontally while light travels. The light follows a longer diagonal path between them, still at speed c. The same tick therefore takes a longer coordinate interval.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "No mechanical damage is required", "body": "Time dilation is not a faulty or friction-slowed clock. Different measurement frames assign different elapsed intervals between the same events. All suitable clocks follow proper-time behaviour, not only the light-clock illustration.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Simultaneous in one frame", "body": "Two separated events can have equal time coordinates in S. If S′ moves relative to S along their separation, they need not have equal t′ coordinates. Simultaneity of separated events is frame-dependent.", "fig": "synchronise", "type": "learn"}, {"chapter": 1, "title": "The train flash thought experiment", "body": "In the platform frame, equal-time flashes at rear and front travel toward a moving midpoint rider. The rider moves toward the front pulse and away from the rear pulse. Reception order differs even before assigning emission coordinates.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Distinguish the two conclusions", "body": "Unequal reception alone follows travel geometry. To infer emission simultaneity in the train frame, use train-frame synchronisation and equal light speed. Do not replace the full argument with what the rider sees.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "The sign of event-order change", "body": "For a train moving right, front and rear flashes simultaneous in the platform frame are not simultaneous in the train frame: the front flash is earlier in the train frame. State the direction and which events before claiming earlier.", "fig": "train", "type": "learn"}, {"chapter": 1, "title": "Local coincidences agree", "body": "If two particles collide at one place and time, all frames agree a collision occurred. Relativity changes coordinate labels, not whether two worldlines meet. A local physical event is not an observer’s illusion.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Causal order is protected", "body": "Events that can be linked by a light-speed-or-slower signal retain their causal order. Some widely separated events with insufficient time for a signal can exchange order between frames. This does not let an effect cause its own earlier cause.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Simultaneity calculation is extension", "body": "The full Lorentz time transformation is a useful extension for numerical separated-event simultaneity. The core lesson requires reasoning with postulates, clocks and frame definitions; we will mark that extra algebra explicitly when used.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: rest-frame light clock", "body": "Two mirrors are 0.300 m apart perpendicular to relative motion. In the clock rest frame, a round trip covers 0.600 m. Tick interval τ = 0.600/(3.00×10⁸) = 2.00 ns.", "fig": "lightClock", "type": "worked"}, {"chapter": 2, "title": "Worked: moving tick at 0.6c", "body": "For β = 0.600, γ = 1/√(1−0.36) = 1.25. Moving-frame interval for the same tick is t = γτ = 2.50 ns. The clock has not changed its own rest-frame mirror separation.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: check the light path length", "body": "In the observing frame light travels c×2.50 ns = 0.750 m per round trip, longer than 0.600 m. Horizontal motion makes the path diagonal, while vacuum c stays constant.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: one half-trip triangle", "body": "One half-trip takes 1.25 ns in the observer frame. Light travels 0.375 m, while the mirror moves 0.225 m at 0.6c. √(0.300²+0.225²) = 0.375 m, checking the geometry.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: two flashes and travel delay", "body": "In a single platform frame, an observer receives a flash from a stationary lamp 300 m away 1.00 μs after emission. A nearer flash may arrive first even if emitted later. Reception order alone is not emission-order evidence.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: remove a delay explicitly", "body": "Flash A is emitted at 0 μs from 600 m and arrives at 2.00 μs. Flash B is emitted at 1.00 μs from 150 m and arrives at 1.50 μs. B is seen first but was emitted later in this frame.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: equal emission times, unequal distances", "body": "Two stationary lamps both emit at t = 0. They are 300 and 900 m from an observer. Their receptions occur at 1.00 and 3.00 μs. Correcting each travel delay recovers simultaneous emission in that frame.", "fig": "synchronise", "type": "worked"}, {"chapter": 2, "title": "Worked: meeting is frame-independent", "body": "A passenger and a door make contact in the train. Train and platform assign different coordinates to the contact but agree contact happened. Do not claim length contraction or clock disagreement can erase a local collision.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: test a source-speed claim", "body": "A source moving at 0.8c emits forward light. Vacuum light measured in an inertial laboratory still has speed c, not 1.8c. The velocity-addition formula later reproduces this result with its denominator.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: separate acceleration evidence", "body": "A rocket’s accelerometer records a nonzero reading while engines fire. This identifies acceleration without contradicting the first postulate, which concerns inertial frames and does not hide acceleration.", "fig": null, "type": "worked"}], "guides": [{"q": "Mirrors 0.600 m apart at rest. Round-trip tick interval?", "value": 4, "unit": "ns", "why": "Round-trip length 1.20 m divided by c gives 4.00 ns.", "tolerance": 0.025}, {"q": "A 4 ns proper tick is observed with γ = 1.25. Interval?", "value": 5, "unit": "ns", "why": "Same two tick events: Δt = γΔτ = 1.25×4 = 5 ns.", "tolerance": 0.025}], "practice": [{"q": "A light clock has mirrors 0.450 m apart. Find its rest round-trip interval and the interval measured when it moves at 0.8c. Explain why c does not change.", "points": ["Rest interval = 0.900/c = 3.00 ns.", "γ = 1/√(1−0.8²) = 5/3.", "Observer interval = 5.00 ns.", "The moving light path is longer while both frames measure vacuum light speed c."]}, {"q": "Two lamps at rest in S, 300 m and 1200 m from an observer, emit simultaneously at t = 0. Find arrival times and explain why reception order does not establish non-simultaneous emission.", "points": ["First travel time = 1.00 μs.", "Second travel time = 4.00 μs.", "Different distances create different arrival times.", "Correcting propagation gives t = 0 for both emissions in S."]}], "tasks": [{"q": "A vacuum light source moves at +0.7c in S. State forward light speed measured in S and explain which postulate rules out 1.7c.", "points": ["Measured vacuum light speed is c.", "Second postulate says it is independent of source motion.", "Classical addition c+0.7c is unsuitable.", "Different frame times and distances replace universal-time assumptions."]}, {"q": "A rest light clock mirror separation is 0.750 m. At speed 0.6c find rest tick, observed tick and observed round-trip path length.", "points": ["Rest tick = 1.50/c = 5.00 ns.", "γ = 1.25.", "Observed tick = 6.25 ns.", "Observed light path = c×6.25 ns = 1.875 m."]}], "bank": [{"q": "Vacuum c depends on constant source speed?", "o": ["Yes", "No", "Only for blue light"], "a": 1, "explain": "The second postulate makes vacuum c invariant across inertial frames."}, {"q": "Moving light-clock path is…", "o": ["longer in the observing frame", "always vertically identical", "slower because c falls"], "a": 0, "explain": "Mirror motion makes a diagonal path."}, {"q": "Simultaneous separated events must be simultaneous in every frame?", "o": ["Yes", "No", "Only if distant"], "a": 1, "explain": "Coordinate simultaneity depends on relative motion and event separation."}, {"q": "An observed arrival order is…", "o": ["always emission order", "affected by travel delay", "a preferred frame"], "a": 1, "explain": "Correct light propagation before assigning event times."}, {"q": "A local collision…", "o": ["occurs in all frame descriptions", "vanishes in some frames", "cannot occur near c"], "a": 0, "explain": "All frames agree on the coincidence event."}, {"q": "Detectable acceleration violates the inertial-frame postulate?", "o": ["Yes", "No", "Only in a rocket"], "a": 1, "explain": "Acceleration is outside the constant-velocity comparison."}], "transfer": [["Simultaneity in a transverse arrangement", "If simultaneous events have no separation along the relative-motion direction, the simple longitudinal simultaneity shift can be zero. Do not say every pair of simultaneous events always changes order."], ["Causality versus coordinate order", "A signal sent and then received cannot have its causal direction reversed by changing inertial frame. Frame-dependent order applies to appropriately separated, causally disconnected events."], ["A medium changes the question", "Light slows in a material because of interaction with that material. The vacuum-speed postulate does not claim every pulse travels at c through every medium."]], "summary": "Explain the two postulates, operational simultaneity and why moving light clocks have longer coordinate intervals.", "mode": "ratios"}, {"id": "relativity-foundations-focus-3", "parent": "relativity-foundations", "title": "Lorentz factor and velocity transformations: signs, limits and checks", "shortTitle": "Gamma & transformations", "subtitle": "Calculate gamma and transform collinear velocities for forward/backward launches, approaching and overtaking cases.", "rows": [{"chapter": 0, "title": "A ratio that organises the effects", "body": "Define β = v/c and γ = 1/√(1−β²). Gamma connects time dilation, length contraction, momentum and energy. It is dimensionless and depends on speed magnitude, not on a chosen plus or minus direction.", "fig": "gammaPlot", "type": "learn"}, {"chapter": 0, "title": "Express speeds consistently", "body": "If v = 0.6c, β = 0.6 directly. If v = 1.80×10⁸ m/s and c = 3.00×10⁸, β = 0.600. Do not square an SI speed while leaving c out of the denominator.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Gamma starts at one", "body": "At rest β = 0, so γ = 1. For every massive object moving with 0 ≤ |β| < 1, γ ≥ 1. A result below one is a warning about formula inversion or calculator brackets.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Approaching c changes the scale", "body": "As β approaches one, 1−β² approaches zero and γ grows without bound. Do not substitute β = 1 for a massive object and report a finite gamma. A photon has no rest frame for this formula.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Negative velocity has the same gamma", "body": "For ±0.8c, β² is 0.64 and γ = 5/3 in both cases. Time and parallel-length ratios depend on this magnitude. Direction still matters in velocity transformations, which use unsquared signed speeds.", "fig": "velocityScene", "type": "learn"}, {"chapter": 0, "title": "Why ordinary mechanics works", "body": "For v much smaller than c, β² is tiny and γ is extremely close to one. Classical equations are useful approximations within this regime. They are not exact laws at every speed.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Keep the whole square root", "body": "Enter 1/sqrt(1−β²). Writing 1/sqrt(1)−β² instead produces 1−β², which is less than one and is not gamma. Use parentheses and check a familiar value such as β = 0.6.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Forward velocity transformation", "body": "If S′ moves at +v relative to S and the object has signed u′ in S′, u = (u′+v)/(1+u′v/c²). Numerator and denominator both matter. This is core Year 12 content in the 2026 syllabus.", "fig": "frames", "type": "learn"}, {"chapter": 1, "title": "Inverse velocity transformation", "body": "To find velocity aboard S′ from a laboratory value u, use u′ = (u−v)/(1−uv/c²). It is the inverse of the forward expression. Decide the requested frame before selecting a formula.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Use fractions of c to simplify", "body": "Let u = ac and v = bc. Then u′/c = (a−b)/(1−ab). The denominator is dimensionless. Multiply the final signed fraction by c if the answer is requested in m/s.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Same-direction overtaking", "body": "With laboratory velocities +0.8c and +0.6c, the faster craft’s velocity measured aboard the slower is not 0.2c. The inverse transformation gives 0.2/(1−0.48)c, larger than the laboratory gap-closing rate.", "fig": "gammaPlot", "type": "learn"}, {"chapter": 1, "title": "Opposite-direction approach", "body": "Two spacecraft at +0.6c and −0.6c have an Earth-coordinate closing rate 1.2c. Neither measures the other exceeding c: the transformed speed magnitude is 1.2/(1+0.36)c.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Moving apart changes signs, not the rule", "body": "When two objects separate in S, still use their signed velocities. The velocity measured aboard one object can be positive or negative according to your axes. Moving away is not a separate formula.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Invariant light is a check", "body": "Substitute u′ = c in the forward transformation: (c+v)/(1+v/c) = c. For u′ = −c, the result is −c. The denominator ensures the postulate is preserved.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: gamma at 0.6c", "body": "β = 0.600. β² = 0.360; 1−β² = 0.640; square root = 0.800. γ = 1/0.800 = 1.25. Showing each operation helps locate a calculator-bracket mistake.", "fig": "velocityScene", "type": "worked"}, {"chapter": 2, "title": "Worked: gamma at 0.8c", "body": "β² = 0.640; 1−β² = 0.360; square root = 0.600. γ = 1.6667. This standard value is useful for checking later time, length and energy calculations.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: solve speed from gamma", "body": "Given γ = 2.00, rearrange 1/γ² = 1−β². Then β = √(1−1/γ²) = √0.75 = 0.866. This gives speed magnitude; direction requires separate information.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: ordinary-speed estimate", "body": "At 30.0 m/s, β = 1.00×10⁻⁷ and β² = 10⁻¹⁴. Gamma differs from one by roughly 5×10⁻¹⁵. A normal calculator may display 1; that is rounding, not a failure of relativity.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: launch from a moving craft", "body": "S′ moves at +0.6c and launches a probe forward at +0.5c relative to itself. u/c = (0.5+0.6)/(1+0.5×0.6) = 1.1/1.3 = 0.846. The classical sum 1.1c is unsuitable.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: launch backward", "body": "The same craft launches a probe at u′ = −0.5c. u/c = (−0.5+0.6)/(1−0.30) = 0.1/0.7 = +0.143. A backward local launch can still move forward in the laboratory.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: approaching spacecraft", "body": "A moves +0.6c and B −0.6c in S. To measure B aboard A, u′/c = (−0.6−0.6)/(1−(−0.6)(0.6)) = −1.2/1.36 = −0.882. Its speed is 0.882c.", "fig": "frames", "type": "worked"}, {"chapter": 2, "title": "Worked: overtaking spacecraft", "body": "B moves +0.8c and A +0.6c in S. A measures B at (0.8−0.6)/(1−0.48)c = +0.385c. S measures the gap shrinking at 0.2c; these are different quantities in different frames.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: transform a photon", "body": "With v = 0.7c and laboratory u = c, u′/c = (1−0.7)/(1−0.7) = 1. Light remains c. Do not use an object-at-rest gamma formula for the photon itself.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: audit the answer", "body": "For two massive objects with sub-c speeds, a transformed magnitude above c indicates a sign or denominator error. Check which frame is moving, which object is observed, and whether the forward or inverse formula matches the knowns.", "fig": null, "type": "worked"}], "guides": [{"q": "γ = 1.25. Find β = v/c.", "value": 0.6, "unit": "", "why": "β = sqrt(1−1/1.25²) = 0.600.", "tolerance": 0.002}, {"q": "S′ moves +0.8c; probe u′ = +0.5c. Find u/c.", "value": 0.9285714285714287, "unit": "", "why": "(0.5+0.8)/(1+0.4) = 0.92857.", "tolerance": 0.002}], "practice": [{"q": "Spacecraft A and B move at +0.8c and −0.8c in Earth frame. Find Earth closing rate and B velocity in A’s frame; explain why these differ.", "points": ["Earth separation closes at 1.6c.", "u′/c = (−0.8−0.8)/(1−(−0.8)(0.8)).", "u′ = −1.6/1.64 c = −0.976c.", "Coordinate closing rate is not the velocity measured in either craft’s rest frame."]}, {"q": "A spacecraft has γ = 2.50. Find its speed magnitude and a forward probe’s laboratory velocity if the probe is launched at +0.4c in the spacecraft frame.", "points": ["β = sqrt(1−1/2.50²) = 0.916515.", "u/c = (0.4+0.916515)/(1+0.4×0.916515).", "u ≈ 0.96334c.", "Gamma gives magnitude; the forward orientation must be specified for the signed velocity."]}], "tasks": [{"q": "A laboratory measures two craft moving right at 0.9c and 0.5c. Find velocity of the faster craft aboard the slower and compare with laboratory closing rate.", "points": ["Laboratory closing rate = 0.4c.", "Transformed velocity = (0.9−0.5)/(1−0.45)c.", "Velocity = 0.727c.", "The two quantities use different frame time/position measurements."]}, {"q": "A craft moves +0.7c and launches a probe backward at −0.8c relative to itself. Find laboratory velocity and its direction.", "points": ["u/c = (−0.8+0.7)/(1−0.56).", "u/c = −0.1/0.44.", "u = −0.227c.", "Negative means left in the chosen laboratory axes."]}], "bank": [{"q": "At β = 0, gamma is…", "o": ["0", "1", "infinite"], "a": 1, "explain": "γ = 1/√1 = 1."}, {"q": "Gamma at −0.8c compared with +0.8c is…", "o": ["equal", "negative", "zero"], "a": 0, "explain": "It depends on β²."}, {"q": "Forward transformation denominator is…", "o": ["1+u′v/c²", "1−u′v/c²", "u′+v"], "a": 0, "explain": "Use the signed product with the plus in the forward transformation."}, {"q": "A one-frame closing rate exceeding c…", "o": ["necessarily violates relativity", "need not be a locally measured relative speed", "means photons rest"], "a": 1, "explain": "Coordinate separation rates are different from transformed velocities."}, {"q": "A photon transformed to another inertial frame has vacuum speed…", "o": ["c", "c+v", "0"], "a": 0, "explain": "The relativistic transformation preserves c."}, {"q": "From gamma, speed magnitude is…", "o": ["c√(1−1/γ²)", "cγ", "c/γ always"], "a": 0, "explain": "Rearrange the squared gamma definition."}], "transfer": [["A two-dimensional warning", "The equations here apply to collinear velocities. A diagonal launch needs the appropriate component transformation; do not use a scalar speed in a one-dimensional formula without checking direction."], ["Forward versus inverse", "If u′ is given aboard the craft and u is asked in S, use forward addition. If u is given in S and the onboard value is asked, subtract the frame speed using the inverse expression."], ["Low-speed recovery", "When uv/c² is tiny, the denominator is near one and the relativistic expressions approach ordinary signed addition/subtraction. Check the regime rather than choosing classical mechanics from habit."]], "summary": "Calculate gamma and transform collinear velocities for forward/backward launches, approaching and overtaking cases.", "mode": "ratios"}, {"id": "relativity-effects-focus-1", "parent": "relativity-effects", "title": "Time dilation: proper clocks, observed intervals and inverse problems", "shortTitle": "Proper time & clocks", "subtitle": "Choose proper time from events and solve direct, inverse, travel and mean-lifetime dilation cases.", "rows": [{"chapter": 0, "title": "Which clock is present at both events?", "body": "For two ticks of one moving clock, that clock is present at both events and records their proper-time interval Δτ. Another inertial frame assigns a longer coordinate interval Δt if the clock moves relative to it.", "fig": "clockPair", "type": "learn"}, {"chapter": 0, "title": "Proper time is an event-pair definition", "body": "It is not always whichever time is given first or is shortest on the page. Identify the two events and the clock that can sit at their common position in a rest frame. A journey between separated Earth locations has a travelling clock’s proper time.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Use the same two events", "body": "A departure and an arrival form one pair; two light receptions form another. Time dilation only compares intervals for the chosen identical events. Combining an emission interval with a reception interval can introduce propagation effects.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The clock rest frame", "body": "When a clock is at rest in S′, its ticks occur at one S′ position. Δτ is measured there. In S, the clock changes position between ticks and Δt is measured using S’s coordinate clocks.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The time-dilation relation", "body": "Δt = γΔτ = Δτ/√(1−v²/c²). The moving-frame coordinate interval is at least as large as the clock’s proper interval. Label times before substituting numbers.", "fig": "lightClock", "type": "learn"}, {"chapter": 0, "title": "Time is not a distance", "body": "Seconds or microseconds remain time units. Gamma is dimensionless. You may use microseconds on both sides without converting if no other equation requires SI seconds.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Do not invert on intuition", "body": "If proper interval is known and laboratory interval is asked, multiply by γ. If laboratory interval is given and onboard interval is asked, divide by γ. The word observed does not decide this automatically.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "A clock’s operation stays normal locally", "body": "The traveller records normal heartbeat, chemistry and clock ticks in their own frame. Dilation is a comparison between frame measurements, not the traveller feeling their seconds become sluggish.", "fig": "delay", "type": "learn"}, {"chapter": 1, "title": "Motion direction does not change gamma", "body": "For the same speed magnitude, motion toward or away gives the same coordinate time-dilation factor. Signals received from an approaching or receding source can have different arrival spacings, which is another effect.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Reciprocal inertial descriptions", "body": "For two inertial observers in relative motion, each assigns the other’s moving clock slower coordinate ticking under their own simultaneity convention. They are not comparing the same remote event selections in a shared universal now.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Aging at reunion is different", "body": "If clocks separate and reunite, compare proper time along their complete paths. A traveller who turns around changes inertial frames. One constant-frame reciprocal argument cannot cover the whole round trip unchanged.", "fig": "clockPair", "type": "learn"}, {"chapter": 1, "title": "Find speed from interval ratio", "body": "γ = Δt/Δτ, then β = √(1−1/γ²). The ratio must be at least one for this moving-clock setup. A ratio below one suggests the intervals were labelled backward.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Travel time in a named frame", "body": "If Earth measures a fixed distance L and ship speed v, Earth time is L/v. Ship proper travel time on an inertial leg is Earth time divided by γ. Do not first contract Earth distance and then use Earth time.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Finite-light-delay corrections", "body": "A remote moving clock’s received tick intervals include changing signal travel time. The simple dilation formula uses corrected frame-coordinate intervals, not automatically raw telescope arrival times.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: moving atomic clock", "body": "A clock’s own ticks are 3.00 s apart. It moves at 0.8c relative to a lab. Δτ = 3.00 s and γ = 5/3, so Δt = 5.00 s for those ticks in lab coordinates.", "fig": "lightClock", "type": "worked"}, {"chapter": 2, "title": "Worked: reverse the known interval", "body": "If the lab instead reports 10.0 s between the same clock’s events at 0.8c, the clock records Δτ = 10.0/(5/3) = 6.00 s. The lab value is the longer interval.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: infer speed", "body": "A clock records 4.00 μs between two events and the lab assigns 5.00 μs. γ = 5/4 = 1.25. β = √(1−1/1.25²) = 0.600. Speed is 1.80×10⁸ m/s.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: unit consistency", "body": "Keeping both intervals in μs makes their ratio dimensionless. Converting only one to seconds would change the ratio by a million. Either convert both or keep the same unit for both.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a one-leg voyage", "body": "An Earth-frame destination is 8.00 light-years away and the ship moves at 0.8c. Since c covers one light-year per year, Earth duration is 8.00/0.8 = 10.0 years.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: onboard one-leg time", "body": "γ = 5/3, so ship proper duration = 10.0/(5/3) = 6.00 years. These are departure and arrival events. At arrival the onboard clock has accumulated six years over that ideal inertial leg.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: particle lifetime", "body": "A particle has mean rest-frame lifetime τ₀ = 2.00 μs and moves at 0.6c. Expected lab mean lifetime = 1.25×2.00 = 2.50 μs. Individual decay times remain random; the mean is not a guaranteed expiry time.", "fig": "delay", "type": "worked"}, {"chapter": 2, "title": "Worked: expected travel scale", "body": "Lab distance based on mean lifetime is vτ_lab = 0.6(3.00×10⁸)(2.50×10⁻⁶) = 450 m. This is a mean characteristic distance, not a boundary beyond which no particle survives.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: clock at rest in lab", "body": "At v = 0, γ = 1 and lab interval equals proper interval. No extra factor is needed. The relation agrees with ordinary timing at rest rather than introducing an unexplained offset.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: reject an optical shortcut", "body": "A receding clock’s pulses can arrive more widely spaced because later pulses travel farther. That widening cannot be attributed entirely to time dilation without correcting propagation. Identify emitted and received events separately.", "fig": null, "type": "worked"}], "guides": [{"q": "Proper interval 8 s; gamma 1.25. Lab interval?", "value": 10, "unit": "s", "why": "Δt = γΔτ = 1.25×8 = 10 s.", "tolerance": 0.025}, {"q": "Lab interval 15 μs at 0.8c. Proper interval?", "value": 9, "unit": "μs", "why": "Divide by γ = 5/3: 15×0.6 = 9 μs.", "tolerance": 0.025}], "practice": [{"q": "A moving clock records 6.00 s while a laboratory assigns 10.0 s to the same events. Find gamma and speed, explaining why 6.00 s is proper time.", "points": ["The clock is present at both events in its rest frame.", "γ = 10.0/6.00 = 5/3.", "β = √(1−1/γ²) = 0.800.", "v = 2.40×10⁸ m/s."]}, {"q": "A destination is 12.0 light-years away in Earth frame. A ship cruises at 0.6c. Find Earth and ship travel times for one inertial leg.", "points": ["Earth time = 12.0/0.6 = 20.0 years.", "γ = 1.25.", "Ship proper time = 20.0/1.25 = 16.0 years.", "The same departure/arrival events are compared; acceleration phases are neglected."]}], "tasks": [{"q": "A particle has mean proper lifetime 3.00 μs and moves at 0.8c. Calculate laboratory mean lifetime and characteristic laboratory travel distance.", "points": ["γ = 5/3.", "Mean laboratory lifetime = 5.00 μs.", "Distance = 0.8c×5.00 μs.", "Distance = 1200 m; individual survival remains random."]}, {"q": "A laboratory interval is 7.50 s and a travelling clock interval is 6.00 s for the same two ticks. Infer speed and distinguish this from uncorrected signal reception spacing.", "points": ["γ = 7.50/6.00 = 1.25.", "Speed = 0.600c.", "Coordinate intervals compare the same events after frame timing is established.", "Raw signal arrival intervals can also include changing propagation delay."]}], "bank": [{"q": "Proper time is measured by…", "o": ["a clock present at both events", "always Earth", "the furthest observer"], "a": 0, "explain": "The event pair is local to that clock in its rest frame."}, {"q": "For a moving clock Δt/Δτ is…", "o": ["γ", "1/γ", "β"], "a": 0, "explain": "Time dilation multiplies proper interval by gamma."}, {"q": "A lab interval 10 s at gamma 2 corresponds to proper…", "o": ["20 s", "5 s", "10 s"], "a": 1, "explain": "Divide lab time by gamma."}, {"q": "Mean lifetime guarantees every particle decays then?", "o": ["Yes", "No", "Only at 0.6c"], "a": 1, "explain": "Decay times are stochastic."}, {"q": "Raw received ticks include…", "o": ["possible propagation changes", "only dilation always", "no light travel"], "a": 0, "explain": "Signal distance can change between emissions."}, {"q": "Toward versus away changes gamma at equal speed?", "o": ["Yes", "No", "Only for Earth"], "a": 1, "explain": "Gamma depends on squared speed magnitude."}], "transfer": [["Different pair, different proper time", "If a ship clock records departure and arrival, its path provides proper time. If Earth observers use two separated clocks, they provide Earth coordinate time. Mark the events before applying an equation."], ["A round trip", "For two equal ideal cruise legs at 0.8c with Earth total 20 years, ship total is 12 years when turnaround duration is neglected. The return changes the traveller’s inertial frame and breaks the naive symmetric reunion argument."], ["No universal slowed biology", "The traveller does not experience time as defective. The younger reunion age is the accumulated proper time on that path, not a malfunction of the clock or body."]], "summary": "Choose proper time from events and solve direct, inverse, travel and mean-lifetime dilation cases.", "mode": "ratios"}, {"id": "relativity-effects-focus-2", "parent": "relativity-effects", "title": "Length contraction: simultaneous endpoints and direction", "shortTitle": "Proper length & geometry", "subtitle": "Measure simultaneous endpoints, contract only the parallel dimension and reconcile journey distances and times.", "rows": [{"chapter": 0, "title": "How do you measure a moving object?", "body": "To measure a moving rod’s length in S, record both endpoint positions at the same S time. Measuring one end now and the other later can include the rod’s motion and is not a valid length measurement.", "fig": "rod", "type": "learn"}, {"chapter": 0, "title": "Proper length belongs to a rest frame", "body": "L₀ is the length measured in the object’s rest frame. It is not automatically the largest distance printed in a question. For a fixed Earth-to-star separation, that separation’s rest frame is Earth in the ideal model.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Moving length is shorter parallel to motion", "body": "L = L₀/γ = L₀√(1−β²). It applies to the dimension parallel to relative velocity. A transverse dimension remains unchanged in the standard aligned-frame comparison.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The object is not physically crushed", "body": "Different frames select simultaneous endpoint events differently. Contraction describes their length measurements, not a force compressing the object in its own frame. The object still measures L₀ locally.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Endpoints must be simultaneous in the measuring frame", "body": "The pair simultaneous in S generally is not simultaneous in S′. This is why simply transforming a previously selected endpoint pair without handling times can give the wrong length.", "fig": "direction", "type": "learn"}, {"chapter": 0, "title": "Photographs are a different measurement", "body": "A photograph collects photons arriving together that may have left different parts at different times. Visual appearance includes travel delays and optical effects. It is not automatically the coordinate contracted length.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Direction is indispensable", "body": "A rectangle moving along x contracts along x, while its y width stays the same. If the question gives a diagonal dimension, resolve its longitudinal and transverse components rather than contract every dimension equally.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Direct calculation", "body": "Given L₀ and v, calculate gamma and divide L₀ by gamma. The answer should not exceed L₀ for this model. A factor greater than one means you probably inverted the relationship.", "fig": "eventMap", "type": "learn"}, {"chapter": 1, "title": "Reverse calculation", "body": "Given moving-frame length L and v, rest length L₀ = γL. This returns the longer rest-frame length. The same physical object must be compared in both descriptions.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Find speed from a length ratio", "body": "L/L₀ = √(1−β²), so β = √(1−(L/L₀)²). Keep the ratio dimensionless with matching length units. The formula gives a speed magnitude, not direction.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Travel through a fixed region", "body": "A ship sees the Earth-fixed journey distance contracted. Earth sees a moving ship’s own length contracted. These are different objects and distances; do not reuse one L₀ label for both.", "fig": "rod", "type": "learn"}, {"chapter": 1, "title": "Time and length work together", "body": "Earth says ship travel time is L₀/v. Ship says a contracted destination distance L₀/γ passes at speed v, so ship time is L₀/(γv). This matches time dilation for the journey event pair.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "A tilted rod extension", "body": "For rest components Lx₀ and Ly₀, moving components are Lx = Lx₀/γ and Ly = Ly₀. Its measured angle can change because the component ratio changes. This extends the core directional contraction reasoning.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "A passing-object clock", "body": "Time from front passing a fixed detector to rear passing is L/v in the detector frame, using contracted length L. Those two events occur at the detector’s one location, so the detector interval is proper for that pair.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: longitudinal rod", "body": "A 10.0 m rest rod moves at 0.8c along its length. γ = 5/3, so S length = 10.0/(5/3) = 6.00 m. This assumes simultaneous S endpoint measurements.", "fig": "direction", "type": "worked"}, {"chapter": 2, "title": "Worked: transverse width", "body": "The same object has rest width 2.00 m perpendicular to motion. S measures 2.00 m in that direction. Applying the factor 0.6 to make 1.20 m would be a directional-model error.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: inverse rod length", "body": "A moving object at 0.6c is measured as 8.00 m parallel to motion. γ = 1.25; rest length L₀ = 1.25×8.00 = 10.0 m. The rest length is larger, as expected.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: infer speed from contraction", "body": "A rod’s measured length is 60.0% of its proper length. β = √(1−0.600²) = 0.800. The velocity may be +0.8c or −0.8c; length alone does not determine the sign.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: atmosphere thickness", "body": "A layer is 3000 m thick in Earth frame and a particle crosses it at 0.8c. In the particle frame the layer thickness along motion is 3000×0.6 = 1800 m. The layer is at rest on Earth, not with the particle.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: compare travel durations", "body": "Earth duration = 3000/(0.8c) = 12.5 μs. Particle-frame duration = 1800/(0.8c) = 7.50 μs. Ratio 12.5/7.50 = 5/3 agrees with time dilation.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: inclined component model", "body": "A rest rod has x component 4.00 m and y component 3.00 m, so proper magnitude is 5.00 m. It moves parallel to x at 0.8c. Contract only x to 2.40 m; y stays 3.00 m.", "fig": "eventMap", "type": "worked"}, {"chapter": 2, "title": "Worked: calculate measured magnitude", "body": "Moving magnitude = √(2.40²+3.00²) = 3.84 m. This is not 5.00×0.6 = 3.00 m because the entire rod was not parallel to motion. The new measured angle has tanθ = 3.00/2.40.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: passing a fixed detector", "body": "A rod with L₀ = 12.0 m moves at 0.8c. Detector-frame length is 7.20 m; front-to-rear passage time = 7.20/(2.40×10⁸) = 30.0 ns. These events are local to the detector.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: avoid a mismatched contraction", "body": "Using rest length 12.0 m with detector-frame velocity in that passage calculation gives 50.0 ns, an inconsistent mix. Use the length measured in the same frame as the time and velocity.", "fig": null, "type": "worked"}], "guides": [{"q": "Proper length 20 m at 0.6c. Parallel moving length?", "value": 16, "unit": "m", "why": "γ=1.25; L=20/1.25=16 m.", "tolerance": 0.025}, {"q": "A moving length is 12 m at 0.8c. Proper length?", "value": 20, "unit": "m", "why": "L₀=γL=(5/3)×12=20 m.", "tolerance": 0.025}], "practice": [{"q": "A rectangular spacecraft has rest length 30.0 m along its velocity and rest width 4.00 m transverse to it. At 0.8c, give both Earth-frame dimensions and the measurement condition.", "points": ["γ=5/3.", "Parallel length = 30.0/(5/3)=18.0 m.", "Transverse width remains 4.00 m.", "Earth must record endpoint coordinates simultaneously in Earth frame."]}, {"q": "A rod’s moving-frame length is 80.0% of proper length. Find speed and explain why a photograph is not automatically this contracted measurement.", "points": ["β=√(1−0.800²)=0.600.", "Speed=1.80×10⁸ m/s.", "Contraction uses simultaneous coordinate endpoints in the measuring frame.", "A photograph mixes emissions from different times because of propagation delay."]}], "tasks": [{"q": "An Earth-fixed distance is 10.0 light-years. A ship moves at 0.6c. Find ship-frame distance and check Earth/ship travel times.", "points": ["γ=1.25.", "Ship distance=8.00 light-years.", "Earth time=10/0.6=16.7 years.", "Ship time=8/0.6=13.3 years, Earth time divided by γ."]}, {"q": "A 15.0 m rest rod passes a stationary detector at 0.8c along its length. Find measured detector-frame length and front-to-rear passing interval.", "points": ["γ=5/3.", "Detector length=9.00 m.", "Interval=L/v=9/(2.40×10⁸).", "Interval=37.5 ns; both events occur at the detector."]}], "bank": [{"q": "Proper length is measured…", "o": ["in object rest frame", "always on Earth", "in the fastest frame"], "a": 0, "explain": "Rest-frame simultaneous endpoints define L₀."}, {"q": "Length parallel to motion is…", "o": ["L₀/γ", "γL₀", "L₀+v"], "a": 0, "explain": "Moving coordinate length is contracted."}, {"q": "Transverse dimension in this model…", "o": ["contracts equally", "is unchanged", "doubles"], "a": 1, "explain": "Contraction is longitudinal."}, {"q": "Endpoint measurements need…", "o": ["same measuring-frame time", "different arbitrary times", "same photon brightness"], "a": 0, "explain": "Simultaneous endpoint coordinates define the length."}, {"q": "Contraction physically crushes a rod in its own frame?", "o": ["Yes", "No", "Only at 0.8c"], "a": 1, "explain": "Its local proper length remains unchanged."}, {"q": "Photographic shape is automatically coordinate length?", "o": ["Yes", "No", "Always for distant objects"], "a": 1, "explain": "A photo includes different emission times and optical delays."}], "transfer": [["A ladder or garage thought experiment", "If a moving ladder fits between simultaneous garage doors in one frame, door events need not be simultaneous in the ladder frame. Frame-dependent simultaneity resolves the apparent contradiction; local contacts agree."], ["A diagonal spacecraft", "Resolve rest dimensions into parallel and perpendicular components before applying contraction. State that the simple component geometry is an extension to the longitudinal core model."], ["A backward-moving rod", "The length factor uses β². Reversing direction at the same speed gives the same contracted length magnitude; the signs still matter in event and velocity descriptions."]], "summary": "Measure simultaneous endpoints, contract only the parallel dimension and reconcile journey distances and times.", "mode": "ratios"}, {"id": "relativity-effects-focus-3", "parent": "relativity-effects", "title": "Muon evidence and twin journeys: reconcile complete scenarios", "shortTitle": "Muons & frame reconciliation", "subtitle": "Reconcile muon time/length descriptions and compare proper aging across idealised multi-stage twin journeys.", "rows": [{"chapter": 0, "title": "One physical result, two explanations", "body": "Muon survival through the atmosphere can be described by a longer Earth-frame mean lifetime or a shorter muon-frame atmospheric thickness. Both frame calculations must predict the same encounter with the ground.", "fig": "muons", "type": "learn"}, {"chapter": 0, "title": "Define the Earth-fixed layer", "body": "Let L₀ be the thickness measured in the atmosphere’s rest frame. Let v be the muon speed relative to Earth and τ₀ its mean lifetime at rest. These subscripts name different rest systems; keep them separate.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Mean lifetime is not half-life", "body": "For exponential decay, a supplied mean lifetime τ differs from half-life T by T=τ ln2. If a problem uses mean lifetime, do not insert it as half-life in a repeated-halving equation. Survival calculations are an optional extension here.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Earth timing", "body": "Earth crossing time is t_E=L₀/v. Earth’s measured mean muon lifetime is γτ₀. Their ratio controls whether many muons can survive the layer; no individual lifetime is guaranteed.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Muon timing", "body": "In the muon frame the layer moves and has thickness L=L₀/γ. The ground reaches the muon after t_μ=L/v=L₀/(γv). The muon’s local mean lifetime remains τ₀.", "fig": "twins", "type": "learn"}, {"chapter": 0, "title": "Compare the dimensionless ratios", "body": "t_E/(γτ₀) equals t_μ/τ₀. Thus both frames give the same decay-survival prediction. Time dilation and length contraction are complementary descriptions, not two factors to apply twice.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The non-relativistic prediction", "body": "Using unmodified τ₀ with Earth distance vτ₀ underestimates the characteristic Earth range at high speed. A discrepancy between that estimate and observed high-speed muons supports the relativistic model.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Muon production and evidence", "body": "Cosmic-ray interactions create muons in the upper atmosphere. Ground detections at rates incompatible with a naive unmodified-lifetime calculation provide evidence. Real flux modelling also uses production distributions, energies and detector response.", "fig": "clockPair", "type": "learn"}, {"chapter": 1, "title": "No all-or-none range", "body": "Mean travel distance vγτ₀ is a characteristic scale. Some particles decay earlier and some survive longer. Saying no muon can travel beyond this distance misunderstands stochastic decay.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Departure and reunion events", "body": "Twins can compare clocks directly at the same departure and reunion locations. Their ages reflect proper times accumulated along different worldlines. Local meetings provide an unambiguous comparison without remote clock synchronisation disputes.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Turnaround changes the traveller’s frame", "body": "The traveller who reverses direction changes velocity and inertial frame. The stay-at-home idealisation can remain in one frame. A reciprocal one-leg argument cannot be copied unchanged to the entire trip.", "fig": "muons", "type": "learn"}, {"chapter": 1, "title": "Acceleration is not simply the aging cause", "body": "Acceleration identifies the frame change and path difference. The unequal elapsed proper times can persist when turnaround duration is very short. Avoid claiming all difference is accumulated only while the engines fire.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Piecewise inertial calculation", "body": "For ideal cruise legs, calculate Earth duration per leg and divide by that leg’s gamma for ship proper duration. Add ship leg times. Finite acceleration stages need their own model rather than the same cruise factor blindly.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Avoid double counting", "body": "Earth crossing time divided by gamma already gives the muon’s proper time. Contracting the distance first gives that same time. Do one consistent frame calculation and use the other as a check.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: a supplied muon case", "body": "Use τ₀=2.20 μs, v=0.8c and Earth layer thickness 1000 m. Gamma is 5/3. These simplified values are supplied exercise data, not a complete measurement of the real atmosphere.", "fig": "twins", "type": "worked"}, {"chapter": 2, "title": "Worked: Earth crossing and lifetime", "body": "t_E=1000/(2.40×10⁸)=4.167 μs. Earth mean lifetime=γτ₀=3.667 μs. Ratio crossing/lifetime≈1.136; survival is possible even though crossing exceeds the mean lifetime.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: muon-frame layer", "body": "L=1000/(5/3)=600 m. Ground-approach time=600/(2.40×10⁸)=2.50 μs. Muon mean lifetime remains 2.20 μs. Ratio 2.50/2.20≈1.136, matching Earth.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: survival fraction extension", "body": "With the supplied exponential mean-lifetime model P=exp(−t/τ), muon frame gives exp(−2.50/2.20)≈0.321. Earth gives exp(−4.167/3.667), the same result. This statistical formula is explicitly extension.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: compare a naive range", "body": "Without dilation, Earth characteristic range would be 0.8c×2.20 μs=528 m. Relativistic range is 0.8c×3.667 μs=880 m. Neither range is a sharp survival cutoff.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a higher-speed case", "body": "At β=√0.99≈0.994987, gamma=10. With the same τ₀, Earth mean lifetime is 22.0 μs and characteristic distance is about 6.57 km. High gamma greatly changes expected survival over kilometre scales.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: equal-speed round trip", "body": "A star is 8.00 light-years from Earth. A ship travels at 0.8c outward and back, with instantaneous-turnaround approximation. Earth duration is 10.0 years per leg, total 20.0 years.", "fig": "clockPair", "type": "worked"}, {"chapter": 2, "title": "Worked: ship proper aging", "body": "Each ship leg takes 10.0/(5/3)=6.00 years. Total ship time=12.0 years. At reunion the ship twin is eight years younger than the Earth twin in this idealised calculation.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: why the symmetry claim fails", "body": "The ship uses one outward inertial frame and a different inward frame. Earth can use one continuous frame. The phrase each sees the other slow does not compare identical remote simultaneity slices across the turnaround.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: account for a finite stop", "body": "If the ship spends 2.00 years at rest relative to Earth at the destination in this simplified model, add 2.00 years to both twins’ elapsed times during that stop. Totals become 22.0 and 14.0 years, still differing by eight years.", "fig": null, "type": "worked"}], "guides": [{"q": "τ₀=2 μs, gamma=5. Earth mean lifetime?", "value": 10, "unit": "μs", "why": "τ_E=γτ₀=10 μs.", "tolerance": 0.025}, {"q": "Earth layer L₀=3000 m at gamma=3. Muon-frame thickness?", "value": 1000, "unit": "m", "why": "L=L₀/γ=1000 m.", "tolerance": 0.025}], "practice": [{"q": "A particle with proper mean lifetime 2.00 μs moves at 0.6c across a 450 m Earth-fixed layer. Compare Earth and particle crossing-time/lifetime ratios.", "points": ["γ=1.25; Earth crossing=450/(0.6c)=2.50 μs.", "Earth mean lifetime=2.50 μs, ratio=1.", "Particle layer=450/1.25=360 m.", "Particle crossing=2.00 μs; proper mean lifetime=2.00 μs, ratio=1."]}, {"q": "A ship travels to a star 6.00 light-years away at 0.6c and immediately returns at the same speed. Find Earth and ship elapsed times and explain the reunion asymmetry.", "points": ["Earth time=2×6/0.6=20.0 years.", "γ=1.25.", "Ship time=20/1.25=16.0 years.", "Traveller changes inertial frame at turnaround; one constant-frame reciprocal argument cannot cover both paths."]}], "tasks": [{"q": "A muon crosses a 2400 m Earth-fixed layer at 0.8c. Its proper mean lifetime is 2.40 μs. Find crossing time in both frames and Earth mean lifetime.", "points": ["γ=5/3.", "Earth crossing=10.0 μs.", "Muon layer=1440 m and crossing=6.00 μs.", "Earth mean lifetime=4.00 μs; ratios 10/4 and 6/2.4 both equal 2.5."]}, {"q": "A ship makes two equal 5.00 Earth-year cruise legs at 0.8c with a 1.00-year Earth-rest stop between. Find total Earth and ship aging under the supplied idealisation.", "points": ["Earth total=5+1+5=11.0 years.", "Ship cruise time per leg=5×0.6=3.00 years.", "At Earth-rest stop, both add 1.00 year.", "Ship total=7.00 years; finite acceleration stages are neglected."]}], "bank": [{"q": "Muon-frame atmosphere is…", "o": ["contracted along motion", "expanded by gamma", "at rest with muon"], "a": 0, "explain": "Earth-fixed length is moving in muon frame."}, {"q": "Muon lifetime in its own frame…", "o": ["stays τ₀", "becomes γ²τ₀", "vanishes"], "a": 0, "explain": "Proper lifetime remains its rest-frame lifetime."}, {"q": "Mean travel range is…", "o": ["a characteristic statistical scale", "an absolute wall", "always Earth altitude"], "a": 0, "explain": "Decay can occur earlier or later than the mean."}, {"q": "Applying both contracted distance and dilated lifetime in one frame…", "o": ["usually double counts", "is always required", "is a unit conversion"], "a": 0, "explain": "Use matching time and length measurements for one frame."}, {"q": "Twin traveller changes…", "o": ["inertial frame at turnaround", "invariant mass necessarily", "light speed"], "a": 0, "explain": "The complete path breaks the naive one-frame symmetry."}, {"q": "Mean lifetime equals half-life?", "o": ["Always", "No, they differ", "Only for muons"], "a": 1, "explain": "For exponential decay T=τ ln2."}], "transfer": [["Unequal-speed legs", "For Earth leg durations 4 years at 0.6c and 6 years at 0.8c, ship aging is 4/1.25+6/(5/3)=6.80 years. Calculate each leg separately rather than average speeds."], ["Particle detection is evidence, not a cartoon", "Real muon observations use energy distributions and experimental uncertainty. The simplified calculation shows the model’s mechanism; it does not claim all atmospheric muons have the same speed or path."], ["A proper-time ledger", "Create one row per cruise, stop or acceleration stage and list the frame and clock interval. Adding a complete path prevents hidden missing time during a turnaround or layover."]], "summary": "Reconcile muon time/length descriptions and compare proper aging across idealised multi-stage twin journeys.", "mode": "ratios"}, {"id": "relativity-energy-focus-1", "parent": "relativity-energy", "title": "Relativistic momentum: invariant mass, signed motion and inverse cases", "shortTitle": "Momentum at high speed", "subtitle": "Calculate signed relativistic momentum, invert it for speed and distinguish invariant mass from frame-dependent energy.", "rows": [{"chapter": 0, "title": "Why momentum needs a new model", "body": "Classical p=mv works well at small v/c. At high speed, experiments require p=γmv. The gamma factor grows with speed; m denotes invariant rest mass throughout this lesson.", "fig": "momentumPlot", "type": "learn"}, {"chapter": 0, "title": "Invariant mass is not a speed dial", "body": "A particle's invariant mass is the same in every inertial frame. Its momentum and total energy depend on the measuring frame. Avoid explaining increasing momentum by claiming invariant mass increases.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Momentum is directional", "body": "For one-dimensional motion, give velocity a sign and use the same sign for momentum. Gamma is positive and depends on speed squared. A left-moving massive particle has negative signed momentum.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The useful dimensionless ratio", "body": "Divide p=γmv by mc to obtain p/(mc)=γβ, where β=v/c. This form separates the scale mc from the speed dependence and makes high-speed comparisons easier.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "SI units first", "body": "Convert mass to kilograms and speed to metres per second when obtaining p in kg m/s. A gram is 10⁻³ kg. Multiplying a dimensionless gamma by mv does not change the momentum unit.", "fig": "velocityScene", "type": "learn"}, {"chapter": 0, "title": "Compute gamma before momentum", "body": "Find β=v/c, then γ=1/√(1−β²), then p=γmv. Keep unrounded intermediate values. Check β<1 for any object with nonzero invariant mass.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Classical and relativistic estimates", "body": "Their ratio is p_rel/p_classical=γ for a specified mass and speed. At β=0.6, gamma=1.25: relativistic momentum is 25% greater than mv, not 25% greater than p_rel.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Momentum at rest", "body": "At v=0, gamma=1 and momentum is zero. Rest energy need not be zero. A zero momentum particle can still have mass and rest energy; momentum and energy answer different questions.", "fig": "invariant", "type": "learn"}, {"chapter": 1, "title": "The inverse momentum problem", "body": "If r=p/(mc), then r²=β²/(1−β²). Rearranging gives β²=r²/(1+r²), so signed β=r/√(1+r²). This inverse is useful when momentum is given instead of speed.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Do not exceed c by division", "body": "Using v=p/m at high momentum ignores gamma and can produce v>c. The relativistic inverse approaches c from below as momentum becomes arbitrarily large.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Comparing particles", "body": "Two particles with the same invariant mass and speed magnitude have equal momentum magnitude. Opposite directions give opposite signed momenta. Different masses multiply the common γv factor.", "fig": "momentumPlot", "type": "learn"}, {"chapter": 1, "title": "Momentum conservation uses one frame", "body": "Calculate all particle momenta in one inertial frame before adding. A momentum value from a spacecraft frame cannot be added directly to one from Earth without transformation.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "An isolated collision", "body": "If external impulse is negligible, total momentum before equals total momentum after, including radiation. High-speed problems also require total energy conservation; classical kinetic-energy equations may fail.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Photons require a different form", "body": "A photon has zero invariant mass and travels at c. Do not substitute m=0 and v=c into γmv: gamma is not finite there. Use photon momentum p=E/c.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: known speed and mass", "body": "For supplied m=2.00×10⁻²⁷ kg and v=+0.6c, beta=0.6 and gamma=1.25. Adopt c=3.00×10⁸ m/s for this exercise.", "fig": "velocityScene", "type": "worked"}, {"chapter": 2, "title": "Worked: substitute and interpret", "body": "p=1.25×2.00×10⁻²⁷×1.80×10⁸=+4.50×10⁻¹⁹ kg m/s. The sign is rightward. Classical mv=3.60×10⁻¹⁹, so the classical estimate is smaller.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: same particle moving left", "body": "At v=−0.6c, gamma remains 1.25 because velocity is squared in its definition. Momentum becomes −4.50×10⁻¹⁹ kg m/s. Its magnitude matches the right-moving case.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a higher-speed comparison", "body": "At v=0.8c, gamma=5/3 and p/(mc)=4/3. At 0.6c, p/(mc)=0.75. Momentum therefore grows by (4/3)/0.75=16/9≈1.78, although speed grows only by 4/3.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: inverse from a ratio", "body": "If measured momentum is p=3mc, then r=3. Beta=3/√10≈0.948683 and gamma=√10≈3.16228. Multiplying γβ gives 3, checking the result.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: negative inverse momentum", "body": "If p=−0.75mc, beta=−0.75/√1.5625=−0.6. Gamma=1.25. Taking only the positive square root would lose the direction that the momentum supplied.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: two symmetric particles", "body": "Two equal-mass particles approach at ±0.8c in their centre-of-momentum frame. Their momenta are ±(4/3)mc, so total momentum is zero. Their total energy is positive and cannot be cancelled by signs.", "fig": "invariant", "type": "worked"}, {"chapter": 2, "title": "Worked: photon recoil bookkeeping", "body": "An isolated initially stationary system emits one photon rightward with energy Eγ. Photon momentum is +Eγ/c, so the remaining system must have momentum −Eγ/c. A second balancing photon could instead keep the remainder at rest.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: mass-unit trap", "body": "A supplied mass of 2.00 mg equals 2.00×10⁻⁶ kg. At 0.6c its momentum is 1.25×2.00×10⁻⁶×1.80×10⁸=450 kg m/s. Treating mg as kg would overestimate by one million.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: low-speed check", "body": "For beta=0.001, gamma≈1.0000005. Relativistic and classical momenta are almost identical. This confirms why the classical model remains useful for school-scale carts, while the high-speed correction matters for particle beams.", "fig": null, "type": "worked"}], "guides": [{"q": "At β=0.8, what is p/(mc)?", "value": 1.3333333333333333, "unit": "", "why": "γβ=(5/3)×0.8=4/3.", "tolerance": 0.025}, {"q": "If p=0.75mc, find β.", "value": 0.6, "unit": "", "why": "β=0.75/√(1+0.75²)=0.6.", "tolerance": 0.025}], "practice": [{"q": "A particle of mass 4.00×10⁻²⁷ kg moves at −0.6c. Find signed relativistic momentum and compare with classical momentum.", "points": ["γ=1.25.", "v=−1.80×10⁸ m/s.", "p=−9.00×10⁻¹⁹ kg m/s.", "Classical p=−7.20×10⁻¹⁹; magnitude ratio=1.25."]}, {"q": "A particle has p=2mc. Determine speed fraction and explain why p/m is inappropriate.", "points": ["β=r/√(1+r²).", "β=2/√5≈0.8944.", "v≈0.8944c<c.", "p/m=2c ignores gamma and is not the high-speed velocity."]}], "tasks": [{"q": "For invariant mass 3.00×10⁻²⁷ kg and velocity +0.8c, calculate momentum.", "points": ["γ=5/3.", "v=2.40×10⁸ m/s.", "p=1.20×10⁻¹⁸ kg m/s.", "Momentum is positive in the chosen axis."]}, {"q": "Given p=−4mc, find signed β and gamma.", "points": ["β=−4/√17.", "β≈−0.970143.", "γ=√17≈4.12311.", "γβ=−4 checks the supplied ratio."]}], "bank": [{"q": "Mass m in p=γmv is…", "o": ["invariant mass", "a mass that grows with speed", "photon energy"], "a": 0, "explain": "Energy and momentum change by frame; invariant mass does not."}, {"q": "For negative velocity gamma is…", "o": ["positive", "negative", "zero"], "a": 0, "explain": "Gamma depends on beta squared."}, {"q": "For β=0.6, p/(mc) is…", "o": ["0.75", "0.6", "1.25"], "a": 0, "explain": "γβ=1.25×0.6."}, {"q": "If r=p/(mc), β equals…", "o": ["r/√(1+r²)", "r always", "√(1+r²)"], "a": 0, "explain": "Rearrange the relativistic momentum expression."}, {"q": "Two opposite equal momenta have…", "o": ["zero total momentum", "zero total energy necessarily", "zero mass necessarily"], "a": 0, "explain": "Signed momenta cancel; positive energies add."}, {"q": "A photon momentum is…", "o": ["E/c", "mc with invariant mass positive", "always zero"], "a": 0, "explain": "Photon energy and momentum obey E=pc."}], "transfer": [["A particle-beam comparison", "For equal masses at beta=0.6 and beta=0.8, calculate both gamma values before comparing momenta. A speed ratio alone omits the different gamma factors."], ["A complete conservation system", "Radiation leaving a box carries momentum. A particle-only subsystem may not conserve momentum if a photon crosses its boundary; include all interacting parts."], ["A frame-change warning", "A pair with zero total momentum in one frame generally has nonzero total momentum in another. Conservation holds within each frame, but the numerical totals need not match across frames."]], "summary": "Calculate signed relativistic momentum, invert it for speed and distinguish invariant mass from frame-dependent energy.", "mode": "energy"}, {"id": "relativity-energy-focus-2", "parent": "relativity-energy", "title": "Rest, total and kinetic energy: direct and inverse high-speed cases", "shortTitle": "Rest & kinetic energy", "subtitle": "Separate rest, total and kinetic energies; convert units and solve inverse energy-momentum cases.", "rows": [{"chapter": 0, "title": "Three energies with different meanings", "body": "Rest energy E₀=mc² belongs to invariant mass m. Total particle energy E=γmc² includes motion in the chosen frame. Kinetic energy K=E−E₀=(γ−1)mc² is the motion contribution.", "fig": "energy", "type": "learn"}, {"chapter": 0, "title": "Rest does not mean no energy", "body": "A massive particle at rest has gamma=1, total energy mc² and kinetic energy zero. Distinguish zero kinetic energy from zero total energy whenever a question says stationary.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Frame-dependent energy", "body": "Different inertial frames generally measure different total and kinetic energies of the same particle. Its invariant mass and rest energy remain unchanged. Always identify the measuring frame for a speed-dependent energy.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "The gamma multiplier", "body": "E/E₀=γ and K/E₀=γ−1. These ratios make it easy to compare quantities without evaluating large powers of c. The two ratios differ by exactly one.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Square c correctly", "body": "With c=3.00×10⁸ m/s, c²=9.00×10¹⁶ m²/s². Multiply mass in kilograms by c² to obtain joules. Squaring only the number 3 but retaining 10⁸ creates a huge error.", "fig": "invariant", "type": "learn"}, {"chapter": 0, "title": "Particle energy units", "body": "One electronvolt is the energy associated with an elementary charge through one volt; use the supplied conversion 1 eV=1.60×10⁻¹⁹ J for calculations here. One MeV is 10⁶ eV.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Mass expressed as energy equivalent", "body": "An electron rest-energy value such as 0.511 MeV is mc², not mass in kilograms. Multiply this energy by gamma to obtain total energy in MeV; divide by c² to obtain mass in SI units if required.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Inverse from kinetic energy", "body": "Given K and E₀, gamma=1+K/E₀. Then beta=√(1−1/γ²). This answers a different question from using gamma=K/E₀, which would omit the rest energy.", "fig": "massSystem", "type": "learn"}, {"chapter": 1, "title": "Inverse from total energy", "body": "If total E is supplied, gamma=E/E₀. Physical massive-particle values have gamma≥1. A stated total energy below E₀ is inconsistent with the specified particle mass.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Why infinite energy is required", "body": "As beta approaches one, gamma grows without bound. Accelerating a nonzero-mass particle to c would require unbounded total energy in this model. Large energy makes speed approach c, not exceed it.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Momentum and energy fit together", "body": "For a single particle E²=(pc)²+(mc²)². All three terms inside the squares have energy units. Total energy is used here, not kinetic energy.", "fig": "energy", "type": "learn"}, {"chapter": 1, "title": "Inverse momentum from energy", "body": "Rearrange to pc=√(E²−E₀²) for momentum magnitude. Direction must come from separate directional information. The square root alone does not identify left or right.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Speed from energy and momentum", "body": "For a massive particle, beta=pc/E. Use consistent units for pc and E. This ratio is less than one when E₀>0, and equals one for an ideal photon.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Classical kinetic energy is a limit", "body": "At small beta, gamma−1≈beta²/2, giving K≈½mv². This is an approximation whose accuracy depends on speed; it cannot replace the high-speed formula indiscriminately.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: energy ratios at 0.6c", "body": "Beta=0.6 gives gamma=1.25. Total energy=1.25E₀ and kinetic energy=0.25E₀. Rest energy remains E₀, not 1.25E₀.", "fig": "invariant", "type": "worked"}, {"chapter": 2, "title": "Worked: SI particle data", "body": "For m=2.00×10⁻²⁷ kg, E₀=2.00×10⁻²⁷×9.00×10¹⁶=1.80×10⁻¹⁰ J. At 0.6c, E=2.25×10⁻¹⁰ J and K=4.50×10⁻¹¹ J.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: electron energy in MeV", "body": "With supplied electron E₀=0.511 MeV and beta=0.8, gamma=5/3. Total E=0.851667 MeV and K=0.340667 MeV. Keep these energy values in MeV consistently.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: convert kinetic energy", "body": "Using 1 eV=1.60×10⁻¹⁹ J, 0.340667 MeV is 0.340667×10⁶×1.60×10⁻¹⁹≈5.45×10⁻¹⁴ J. The MeV-to-eV multiplier cannot be omitted.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: kinetic energy equals rest energy", "body": "If K=E₀, then gamma=2. Beta=√(1−1/4)=√3/2≈0.866025. Total energy is 2E₀; confusing total and kinetic would wrongly predict gamma=1.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: total energy five times rest", "body": "If E=5E₀, gamma=5, beta=√(24/25)≈0.979796 and K=4E₀. The speed is below c despite the large energy ratio.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: energy-momentum triangle", "body": "For supplied rest energy 3.00 MeV and pc=4.00 MeV, E=√(9+16)=5.00 MeV. K=2.00 MeV and beta=4/5=0.8. This is one particle with consistent invariant mass.", "fig": "massSystem", "type": "worked"}, {"chapter": 2, "title": "Worked: recover momentum", "body": "For E=10.0 MeV and E₀=6.00 MeV, pc=√(100−36)=8.00 MeV. Momentum magnitude is 8.00 MeV/c; beta=0.8 and gamma=10/6=5/3.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: reject inconsistent data", "body": "A particle specified with rest energy 6 MeV cannot have total energy 4 MeV in any inertial frame. E≥E₀ follows from gamma≥1; a negative square-root argument signals a data or interpretation error.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: compare the classical estimate", "body": "At beta=0.8, exact K/E₀=2/3≈0.6667. Classical ½mv²/E₀=beta²/2=0.32, substantially smaller. The comparison explicitly uses the same mass and speed in both models.", "fig": null, "type": "worked"}], "guides": [{"q": "K=3E₀. Find gamma.", "value": 4, "unit": "", "why": "γ=1+K/E₀=4.", "tolerance": 0.025}, {"q": "E=5 MeV and E₀=3 MeV. Find pc.", "value": 4, "unit": "MeV", "why": "pc=√(25−9)=4 MeV.", "tolerance": 0.025}], "practice": [{"q": "A particle has rest energy 2.00 MeV and kinetic energy 6.00 MeV. Find total energy, gamma and speed fraction.", "points": ["E=8.00 MeV.", "γ=E/E₀=4.", "β=√(15/16)≈0.968246.", "Use total energy, not kinetic energy, in gamma."]}, {"q": "A particle has E₀=5.00 MeV and pc=12.0 MeV. Find E, K and beta.", "points": ["E=√(25+144)=13.0 MeV.", "K=13−5=8.00 MeV.", "β=pc/E=12/13≈0.923077.", "Both sides of the invariant relation are energy quantities."]}], "tasks": [{"q": "With m=4.00×10⁻²⁷ kg and speed 0.6c, find rest, total and kinetic energies in J.", "points": ["E₀=3.60×10⁻¹⁰ J.", "γ=1.25.", "E=4.50×10⁻¹⁰ J.", "K=9.00×10⁻¹¹ J."]}, {"q": "A particle has total energy 17.0 MeV and rest energy 8.00 MeV. Find pc and beta.", "points": ["pc=√(17²−8²).", "pc=15.0 MeV.", "β=15/17≈0.882353.", "K=9.00 MeV; total energy exceeds rest energy."]}], "bank": [{"q": "At rest kinetic energy is…", "o": ["zero", "mc²", "infinite"], "a": 0, "explain": "Total rest energy remains mc²."}, {"q": "If K=2E₀ gamma is…", "o": ["3", "2", "1"], "a": 0, "explain": "Total energy includes rest energy, so γ=1+K/E₀=3."}, {"q": "Invariant relation uses…", "o": ["total E", "K in place of E", "only rest E"], "a": 0, "explain": "E²=(pc)²+E₀²."}, {"q": "For beta=0.8, K/E₀ is…", "o": ["2/3", "5/3", "0.8"], "a": 0, "explain": "Gamma is 5/3; subtract one."}, {"q": "A massive particle total energy is…", "o": ["at least mc²", "below mc² always", "identical in all frames"], "a": 0, "explain": "Gamma is at least one."}, {"q": "One MeV equals…", "o": ["10⁶ eV", "10⁻⁶ eV", "one kilogram"], "a": 0, "explain": "Mega means one million."}], "transfer": [["Energy added at nearly c", "Increasing gamma from 10 to 20 doubles total energy while beta changes from about 0.99499 to 0.99875. Speed increments shrink even as energy increases substantially."], ["An inverse problem with direction", "Energy data recover speed magnitude. If the particle moves left, attach a negative velocity sign after calculating beta; energy alone cannot determine the sign."], ["Check two routes", "For a specified gamma, calculate beta and γβ, then check E²−(pc)²=E₀² using ratios. Agreement verifies that total energy and momentum refer to the same particle and frame."]], "summary": "Separate rest, total and kinetic energies; convert units and solve inverse energy-momentum cases.", "mode": "energy"}, {"id": "relativity-energy-focus-3", "parent": "relativity-energy", "title": "Reaction energy, photons and the mass of complete systems", "shortTitle": "Reactions & system mass", "subtitle": "Track reaction rest energy, photon momentum and invariant mass of multi-particle systems.", "rows": [{"chapter": 0, "title": "Choose the entire system", "body": "A reaction calculation needs a boundary identifying all initial and final particles and radiation. Total energy and momentum are conserved for an isolated complete system. Rest masses of individual particles need not simply add unchanged through a reaction.", "fig": "annihilation", "type": "learn"}, {"chapter": 0, "title": "Reaction rest-energy difference", "body": "If initial rest masses exceed final rest masses by Δm, the rest-energy decrease Δmc² can appear as kinetic energy or radiation. It is a change in energy distribution, not energy created from nothing.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Sign of Q", "body": "Define Q=(sum initial rest masses−sum final rest masses)c². Positive Q means rest energy is released into other forms. Negative Q means energy must be supplied; threshold conditions can also involve momentum.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Use masses of matching type", "body": "Use supplied consistent nuclear or atomic masses. Mixing bare nuclei with neutral-atom masses can incorrectly count electrons. State which mass convention a question supplies before subtracting.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Mass defect units", "body": "If Δm is supplied in kg, Q=Δmc² gives joules. If Δm is in unified atomic mass units, use a supplied u-to-energy conversion. Neither a MeV value nor a u value is already a kilogram.", "fig": "massSystem", "type": "learn"}, {"chapter": 0, "title": "Photons carry energy and momentum", "body": "For a photon E=hf and p=E/c. Its invariant mass is zero. Zero invariant mass does not mean zero energy or zero momentum.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Why one photon may be impossible", "body": "An isolated electron and positron initially at rest together have zero total momentum but positive total energy. A single final photon cannot have zero momentum while carrying that positive energy.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Two photons at rest annihilation", "body": "In the initial centre-of-momentum frame, two photons can travel in opposite directions with equal energies. Their vector momenta cancel while energies add. This is the simplest two-photon scenario.", "fig": "invariant", "type": "learn"}, {"chapter": 1, "title": "Moving annihilation is different", "body": "If the initial system has nonzero momentum in the chosen frame, the photon energies or directions need not match the symmetric rest-frame case. Conserve both total energy and vector momentum in that frame.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Pair production conditions", "body": "Photon energy can form an electron-positron pair, but momentum must also be conserved. A nearby nucleus or another interaction partner can absorb recoil. A lone photon cannot form the pair in empty space while satisfying both conservations.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "The rest-energy minimum", "body": "Electron and positron rest energies total 1.022 MeV using 0.511 MeV each. A real threshold with a recoiling finite-mass partner is slightly above the simple rest-energy sum; supplied models determine how much.", "fig": "annihilation", "type": "learn"}, {"chapter": 1, "title": "System invariant mass", "body": "For a whole isolated system, M²c⁴=E_total²−p_total²c². System mass includes rest-frame internal kinetic energy, thermal energy and radiation. It need not equal the sum of constituent invariant masses.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Two photons can have system mass", "body": "Opposite equal-energy photons have zero total momentum and positive total energy. Their combined invariant mass is E_total/c² although each photon's invariant mass is zero.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Contained energy and box mass", "body": "Heating a closed box or storing radiation increases its rest-frame total energy and hence its system mass by ΔE/c². Identify containment: escaping radiation removes energy from the box subsystem.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: annihilation energy", "body": "An electron and positron annihilate from rest in their common frame. Supplied rest energy per particle is 0.511 MeV, so initial total energy is 1.022 MeV and momentum is zero.", "fig": "massSystem", "type": "worked"}, {"chapter": 2, "title": "Worked: assign two photons", "body": "Opposite equal photon energies are each 0.511 MeV. Each momentum magnitude is 0.511 MeV/c. Opposite directions make their total momentum zero, preserving the initial value.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: photon frequency", "body": "Convert 0.511 MeV using 1 eV=1.60×10⁻¹⁹ J: E≈8.176×10⁻¹⁴ J. With supplied h=6.63×10⁻³⁴ J s, f=E/h≈1.23×10²⁰ Hz.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a supplied reaction mass change", "body": "An isolated reaction has initial rest-mass sum 8.00×10⁻²⁷ kg and final sum 7.98×10⁻²⁷ kg. Δm=2.00×10⁻²⁹ kg, not 0.02 kg.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: released energy in SI", "body": "Q=2.00×10⁻²⁹×9.00×10¹⁶=1.80×10⁻¹² J. This is available to final kinetic energy and radiation under the supplied isolated-system assumptions.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: supplied u conversion", "body": "If Δm=0.00400 u and supplied 1 u c²=931.5 MeV, Q=0.00400×931.5=3.726 MeV. Convert units only if the required final unit is joules.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: opposite photons and system mass", "body": "Two opposite photons each carry 3.00 MeV. Total E=6.00 MeV and total p=0, so Mc²=6.00 MeV. Their combined mass is nonzero despite zero individual invariant masses.", "fig": "invariant", "type": "worked"}, {"chapter": 2, "title": "Worked: same-direction photons", "body": "Two photons each 3.00 MeV travel in the same direction. E_total=6.00 MeV and p_total c=6.00 MeV, giving Mc²=0. Different geometry changes system invariant mass.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: unequal opposite photons", "body": "For opposite photons of 4.00 and 1.00 MeV, E_total=5.00 MeV and |p_total|c=3.00 MeV. Mc²=√(25−9)=4.00 MeV. The chosen frame is not their zero-momentum frame.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a warmed closed box", "body": "If contained internal energy increases by 900 J, mass increases by 900/(9.00×10¹⁶)=1.00×10⁻¹⁴ kg. The change is tiny but the relation uses total system energy, not photon rest mass.", "fig": null, "type": "worked"}], "guides": [{"q": "Rest-mass decrease is 1.00×10⁻²⁹ kg. Released energy?", "value": 9e-13, "unit": "J", "why": "Q=Δmc²=9.00×10⁻¹³ J.", "tolerance": 1e-14}, {"q": "Opposite photons of 5 and 5 MeV: system Mc²?", "value": 10, "unit": "MeV", "why": "Total momentum is zero; system rest energy equals total 10 MeV.", "tolerance": 0.025}], "practice": [{"q": "Opposite photons have energies 9.00 and 4.00 MeV. Find total energy, magnitude p_total c and system rest energy Mc².", "points": ["E_total=13.0 MeV.", "|p_total|c=5.00 MeV.", "Mc²=√(169−25)=12.0 MeV.", "Each photon remains individually zero-invariant-mass."]}, {"q": "A supplied reaction loses 0.00200 u in rest-mass sum. With 1 u c²=931.5 MeV, calculate Q and identify possible output forms.", "points": ["Q=0.00200×931.5.", "Q=1.863 MeV.", "Positive Q means rest energy is released.", "It can appear as kinetic energy or photons subject to momentum conservation."]}], "tasks": [{"q": "A closed box receives and retains 1800 J of internal energy at rest. Calculate its mass increase using c=3.00×10⁸ m/s.", "points": ["ΔM=ΔE/c².", "c²=9.00×10¹⁶.", "ΔM=2.00×10⁻¹⁴ kg.", "Retained energy contributes to total system invariant mass."]}, {"q": "An electron-positron pair annihilates from rest into two photons. With E₀=0.511 MeV each, find photon energies and explain why one isolated photon cannot be the entire output.", "points": ["Initial E_total=1.022 MeV.", "Initial total momentum=0.", "Two opposite photons each 0.511 MeV balance momentum.", "One energy-carrying photon has nonzero momentum and cannot alone conserve the initial zero momentum."]}], "bank": [{"q": "Photon invariant mass is…", "o": ["zero", "E/c² always", "infinite"], "a": 0, "explain": "Energy and momentum remain nonzero."}, {"q": "Opposite equal photons have system mass…", "o": ["nonzero", "always zero", "negative"], "a": 0, "explain": "Their total momentum is zero and total energy positive."}, {"q": "Q positive means…", "o": ["rest energy released", "total energy created", "momentum disappears"], "a": 0, "explain": "Rest energy becomes kinetic energy or radiation."}, {"q": "An isolated rest pair can annihilate into one photon alone?", "o": ["No", "Yes always", "Only if masses match"], "a": 0, "explain": "One photon cannot preserve zero total momentum."}, {"q": "Warming a closed box changes system mass by…", "o": ["ΔE/c²", "ΔE/c", "zero necessarily"], "a": 0, "explain": "Internal rest-frame energy contributes to system mass."}, {"q": "Pair-production modelling must conserve…", "o": ["energy and momentum", "energy only", "rest-mass sum only"], "a": 0, "explain": "A recoil partner is needed for a single incident photon."}], "transfer": [["An open-box boundary", "If radiation leaves a box, the box loses energy and recoils; include outgoing photons for complete conservation. Do not assign conserved energy to an open subsystem."], ["Nuclear versus particle contexts", "The same rest-energy bookkeeping can describe nuclear reactions and particle reactions, but mass conventions and recoil assumptions differ. Read supplied data before selecting a conversion."], ["Geometry changes mass", "Compare same-direction and opposite-direction photon pairs with the same total energy. Their different total momenta give different system invariant masses, demonstrating why mass cannot be inferred from energy alone in an arbitrary frame."]], "summary": "Track reaction rest energy, photon momentum and invariant mass of multi-particle systems.", "mode": null}, {"id": "general-relativity-focus-1", "parent": "general-relativity", "title": "Equivalence and curved spacetime: gravity, support and free fall", "shortTitle": "Equivalence & free fall", "subtitle": "Explain support, local equivalence, free fall and tidal limitations using explicit local scenarios.", "rows": [{"chapter": 0, "title": "Start with what a scale measures", "body": "A scale measures the support force exerted on a body, not the gravitational field directly. An observer can be in a gravitational field yet read zero on a scale during ideal free fall.", "fig": "elevator", "type": "learn"}, {"chapter": 0, "title": "A supported laboratory", "body": "In a laboratory stationary on Earth, the floor supports the observer upward. Gravity acts downward. For no acceleration, the support force balances gravity in a Newtonian local description.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "An accelerating rocket", "body": "Far from significant gravity, a rocket accelerating upward pushes its floor into the observer. The observer feels a support force and a released object accelerates toward the floor relative to the rocket.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Local equivalence", "body": "A sufficiently small laboratory cannot distinguish a uniform gravitational field from a corresponding uniform acceleration using local experiments alone. This is a local statement; it does not equate every global feature of the two situations.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Free fall removes support", "body": "In an ideal freely falling laboratory, the observer and released object follow nearby falling paths together. With no floor force, the scale reading is zero. Earth's gravitational field has not vanished.", "fig": "freefall", "type": "learn"}, {"chapter": 0, "title": "Inertial motion locally", "body": "General relativity describes freely falling motion as locally inertial motion through spacetime. A small falling laboratory can approximate an inertial frame even when its Earth-coordinate position accelerates.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Support requires acceleration away from free fall", "body": "A person standing on Earth is held away from the natural free-fall path by the floor. The feeling of weight corresponds to that support interaction. This reverses the everyday intuition that resting on Earth must be the most inertial state.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Tidal effects limit equivalence", "body": "Gravity can vary across an extended laboratory. Nearby freely falling objects may move relative to one another because the field differs with position. Such tidal effects can reveal curvature and cannot be transformed away over a large region.", "fig": "tidal", "type": "learn"}, {"chapter": 1, "title": "Vertical tidal separation", "body": "Two particles at different heights can experience different gravitational accelerations. Their relative separation can change during free fall. A sufficiently small region reduces but does not universally eliminate these differences.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Horizontal convergence", "body": "Two falling particles separated horizontally may follow directions toward the same gravitating centre. Their paths can converge. Arrows on a tidal diagram describe relative geometry, not an attractive force between the particles themselves.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Spacetime includes time", "body": "Spacetime is a combined description of three spatial dimensions and time. Curvature changes relationships between events and free-fall paths. A two-dimensional stretched-sheet picture cannot represent every aspect.", "fig": "elevator", "type": "learn"}, {"chapter": 1, "title": "Mass-energy affects geometry", "body": "General relativity links matter and energy to spacetime geometry. Bodies in free fall follow paths shaped by that geometry. At weak fields and low speeds, Newtonian gravity remains an excellent approximation.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "A geodesic is a free-fall path", "body": "The word geodesic names a natural path through spacetime for a freely falling object. It need not look straight in Earth coordinates. A curved drawing is not itself proof of a contact force acting sideways.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Limits of the rubber-sheet analogy", "body": "A sheet diagram can suggest that geometry changes paths, but it uses an external downward gravity to make the depression and omits time. Use it as a limited analogy, not the literal mechanism of spacetime curvature.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: supported passenger", "body": "A 60.0 kg person stands at rest on Earth with supplied g=9.80 m/s². A local Newtonian force balance gives N=mg=588 N. The scale detects this upward support.", "fig": "freefall", "type": "worked"}, {"chapter": 2, "title": "Worked: rocket equivalent locally", "body": "A rocket far from gravity accelerates upward at 9.80 m/s². The same person's support force is N=ma=588 N. Similar local support measurements cannot alone tell which laboratory arrangement is present.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: released ball in the rocket", "body": "After release, a ball is approximately inertial in the outside frame while the rocket floor accelerates upward. Relative to the rocket, the ball approaches the floor. The explanation uses frame motion rather than claiming distant Earth gravity acts inside the rocket.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a falling lift", "body": "Neglect air resistance and suppose the person and lift both accelerate downward at g. Newtonian N−mg=−mg gives N=0. The person is locally weightless although gravitational acceleration in Earth coordinates is not zero.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: an orbiting astronaut", "body": "Astronaut and spacecraft continuously fall together along an orbit. The astronaut has negligible support force in the cabin. Orbit is not a location where gravity disappears; forward motion and free fall maintain the orbit.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: accelerating upward on Earth", "body": "For supplied upward lift acceleration 2.00 m/s², N=m(g+a)=60×11.8=708 N. This force calculation is local Newtonian bookkeeping; it is not a quantitative curvature calculation.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: accelerating downward less than g", "body": "For downward acceleration 2.00 m/s², N=m(g−2)=468 N. A reduced scale reading is not the same as zero gravity. The floor still supports the person.", "fig": "tidal", "type": "worked"}, {"chapter": 2, "title": "Worked: distinguish an extended lab", "body": "If separated released test masses change their relative separation while both fall freely, a tidal gradient is present. A perfectly uniform acceleration model cannot reproduce every extended gravitational effect.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: diagnose a misleading picture", "body": "A ball rolling on a curved rubber sheet is pulled by ordinary gravity toward the sheet. Spacetime has no required physical sheet or external downward direction. State the analogy's purpose and its limitation together.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: choose the applicable model", "body": "For a nearby small lift force problem, use supplied g and Newton's second law. For qualitative clock, light-path or tidal-curvature questions, explain the relativistic principle. Neither model should be used outside its stated approximation without justification.", "fig": null, "type": "worked"}], "guides": [{"q": "60 kg person in rocket with acceleration 5 m/s² far from gravity: N?", "value": 300, "unit": "N", "why": "N=ma=60×5=300 N.", "tolerance": 0.025}, {"q": "50 kg person at rest with g=9.8 m/s²: N?", "value": 490, "unit": "N", "why": "N=mg=490 N.", "tolerance": 0.025}], "practice": [{"q": "Compare a supported Earth laboratory and an accelerating rocket far from gravity. Explain what local scale measurements can and cannot establish.", "points": ["Both can produce the same support force locally.", "Earth lab floor balances gravity; rocket floor accelerates the person.", "Local equivalence applies in a sufficiently small region.", "Extended tidal measurements can distinguish gravitational gradients."]}, {"q": "An astronaut is weightless in orbit. Explain why this does not mean no gravity and identify what a scale measures.", "points": ["Astronaut and spacecraft fall together.", "Gravity curves their Earth-coordinate paths.", "A scale measures support force.", "Negligible cabin support means near-zero apparent weight."]}], "tasks": [{"q": "A 75 kg person is supported by an Earth lift accelerating upward at 1.20 m/s². Use g=9.80 to find scale reading and distinguish it from gravitational force.", "points": ["Gravitational force=735 N downward.", "N−mg=ma.", "N=75×11.0=825 N.", "Scale reads upward support magnitude, larger than mg."]}, {"q": "Two separated freely falling particles approach one another. Explain how this can reveal a limitation of a uniform-acceleration laboratory analogy.", "points": ["Field direction or strength can vary across space.", "Different free-fall paths change separation.", "These are tidal effects.", "Local equivalence does not remove all extended curvature effects."]}], "bank": [{"q": "A scale measures…", "o": ["support force", "gravity directly in all cases", "curvature numerically"], "a": 0, "explain": "The sensor detects the contact support."}, {"q": "Weightless orbit means…", "o": ["free fall with little support", "no gravitational field", "zero invariant mass"], "a": 0, "explain": "Astronaut and craft fall together."}, {"q": "Equivalence is principally…", "o": ["local", "an identity of every global field", "a ban on acceleration"], "a": 0, "explain": "Extended tidal differences matter."}, {"q": "A freely falling small lab is…", "o": ["locally approximately inertial", "always supported", "outside spacetime"], "a": 0, "explain": "Nearby free-fall motion defines a local inertial approximation."}, {"q": "Tidal effects involve…", "o": ["field differences across positions", "mass changing with speed", "only friction"], "a": 0, "explain": "Separated geodesics can approach or diverge."}, {"q": "Rubber sheet pictures omit…", "o": ["the full role of time and dimensions", "all geometric ideas", "any limitations"], "a": 0, "explain": "They are limited analogies, not literal spacetime."}], "transfer": [["Model boundary", "A force-balance calculation can describe a local lift while the general-relativity explanation describes why free fall is locally natural. State which question each description answers."], ["Finite laboratory", "A laboratory spanning a large region can detect a gravity gradient. Shrinking it supports the local approximation; calling all gravitational fields exactly uniform loses the crucial limitation."], ["A rotating laboratory", "Rotation can be detected with local inertial instruments. Do not extend constant-velocity special-relativity arguments to a turning rocket without identifying acceleration."]], "summary": "Explain support, local equivalence, free fall and tidal limitations using explicit local scenarios.", "mode": null}, {"id": "general-relativity-focus-2", "parent": "general-relativity", "title": "Gravitational time and GPS: separate height and speed effects", "shortTitle": "Clock height & GPS", "subtitle": "Combine signed satellite clock effects and explain gravitational redshift with clearly defined endpoints.", "rows": [{"chapter": 0, "title": "Clocks at different gravitational potentials", "body": "Stationary clocks at higher gravitational potential run faster relative to comparable stationary lower clocks in a weak gravitational field. The comparison requires a defined reference and a method of exchanging signals.", "fig": "gps", "type": "learn"}, {"chapter": 0, "title": "Higher and lower in the Earth setting", "body": "Near Earth, higher altitude usually means higher gravitational potential and less-negative Newtonian potential. Do not confuse greater potential with greater gravitational field strength; field strength generally decreases with altitude.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Compare elapsed readings operationally", "body": "Specify which clocks are compared, their paths and the reference used. A clock-time difference can accumulate over a long duration even when the fractional rate difference is extremely small.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Motion contributes separately", "body": "A satellite clock also moves relative to Earth. Special-relativistic speed-related time dilation tends to make it run slower relative to the chosen ground comparison. Gravitational height tends to make it run faster in the GPS example.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Opposite signs are essential", "body": "The gravitational and speed corrections in a typical GPS explanation oppose one another. Adding their magnitudes loses this distinction. Name the sign convention, such as satellite clock gain positive relative to ground.", "fig": "redshift", "type": "learn"}, {"chapter": 0, "title": "Orbit matters", "body": "Height and orbital speed influence the effects. Numerical offsets quoted for one GPS orbit are not universal for every satellite. Use supplied exercise data instead of treating one pair of numbers as constants of nature.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "GPS relies on timing", "body": "Satellite positioning uses signal timing and known satellite information. Light travels about 300 m in one microsecond with c=3.00×10⁸ m/s. Small uncorrected time offsets can create large range-equivalent errors.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Range error versus position error", "body": "The simple quantity cΔt is a signal path-length error equivalent. Actual navigation uses multiple satellites, receiver clock estimation and geometry. Do not claim cΔt alone equals every user's exact position error.", "fig": "clockPair", "type": "learn"}, {"chapter": 1, "title": "Gravitational redshift direction", "body": "Light emitted lower in gravitational potential and received higher is measured at lower frequency by the higher stationary receiver. Its received wavelength is greater. This is gravitational redshift in the stated arrangement.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Reverse the path", "body": "Light travelling downward to a lower stationary receiver is measured at higher frequency in the corresponding idealised comparison. Swapping emitter and receiver reverses the effect; memorising only light loses energy is insufficient.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Local c remains c", "body": "Gravitational frequency shifts do not mean local vacuum light speed changes from c for an inertial local measurement. Frequency and wavelength can change consistently while their local product remains c.", "fig": "gps", "type": "learn"}, {"chapter": 1, "title": "Signal travel and clock rate are different", "body": "A changing travel distance can alter signal arrival spacing. Separate that propagation geometry from intrinsic clock-rate comparison and gravitational frequency shift. Explain what the experiment corrects.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Core qualitative understanding", "body": "The core discussion here concerns gravitational time dilation and applications. A numerical weak-field formula is an explicitly supplied extension model; no advanced field-equation derivation is assumed.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Supplied weak-field extension", "body": "For stationary clocks in a weak field, fractional rate difference can be approximated by ΔΦ/c², with ΔΦ=Φ_higher−Φ_lower. Near Earth over a small height interval, supplied ΔΦ≈gΔh gives a positive upper-clock gain.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: supplied GPS rate ledger", "body": "Suppose satellite gain from gravity is +45 μs/day and speed effect is −7 μs/day relative to ground. These are rounded exercise values for a representative situation, not universal orbit data.", "fig": "redshift", "type": "worked"}, {"chapter": 2, "title": "Worked: combine signed offsets", "body": "Net satellite gain is +45−7=+38 μs/day. A positive result means the uncorrected satellite clock gets ahead of the reference. Saying both effects slow it would predict the wrong sign.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: two-day accumulation", "body": "Assuming the supplied rates stay constant, offset after two days is +76 μs. This linear accumulation is a model for a fixed rate error; operational systems continuously correct timing.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: range-equivalent error", "body": "One day's 38 μs gives cΔt=3.00×10⁸×38×10⁻⁶=11400 m=11.4 km. This is a timing-to-range equivalent, not a complete receiver position-error calculation.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: different supplied orbit", "body": "If gravity gives +20 μs/day and motion gives −30 μs/day, net offset is −10 μs/day. The speed effect wins in this supplied scenario. Height alone cannot determine the net sign.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: supplied near-Earth extension", "body": "For Δh=100 m, g=9.80 m/s² and c=3.00×10⁸ m/s, fractional upper-clock gain≈980/(9.00×10¹⁶)=1.089×10⁻¹⁴. The weak-field small-height model is explicitly supplied.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: daily upper-clock gain extension", "body": "Multiply that fraction by 86400 s: gain≈9.41×10⁻¹⁰ s=0.941 ns per day. Use seconds before converting to nanoseconds; a nanosecond is 10⁻⁹ s.", "fig": "clockPair", "type": "worked"}, {"chapter": 2, "title": "Worked: qualitative upward photon", "body": "A lower emitter sends upward light to a higher stationary receiver. The higher receiver measures reduced frequency and increased wavelength, while local vacuum speed remains c. Identify both endpoints before selecting redshift.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: avoid a misleading conclusion", "body": "A high-altitude aircraft clock has both a gravitational and a speed contribution. Without its path, speed and duration, higher altitude alone is insufficient to calculate or guarantee the total accumulated difference.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: clock synchronisation wording", "body": "Two clocks compared through signals need propagation delay handled in the stated coordinate model. A later-arriving signal is not automatically evidence for a slower emitter clock. Rate and transit-time corrections answer different questions.", "fig": null, "type": "worked"}], "guides": [{"q": "Given +40 and −8 μs/day, net satellite offset?", "value": 32, "unit": "μs/day", "why": "Add signed contributions: 40−8=32.", "tolerance": 0.025}, {"q": "A 2 μs timing offset corresponds to what cΔt?", "value": 600, "unit": "m", "why": "3.00×10⁸×2×10⁻⁶=600 m.", "tolerance": 0.025}], "practice": [{"q": "Given gravitational +46 μs/day and speed −8 μs/day relative to ground, find the net uncorrected satellite offset after three days and its cΔt range equivalent.", "points": ["Net=+38 μs/day.", "Three-day offset=+114 μs.", "cΔt=34200 m=34.2 km.", "This is range-equivalent timing error; positioning also depends on receiver clock and satellite geometry."]}, {"q": "Explain upward gravitational redshift between stationary emitter and receiver, and distinguish it from local vacuum light speed.", "points": ["Emitter is lower, receiver higher in potential.", "Higher receiver measures lower frequency.", "Received wavelength is greater.", "Local vacuum speed remains c."]}], "tasks": [{"q": "Supplied orbit corrections are +18 μs/day gravitational and −25 μs/day speed. Find net offset after four days and interpret sign.", "points": ["Net=−7 μs/day.", "After four days=−28 μs.", "Satellite clock is behind the ground reference under this convention.", "Both signed effects must be included; quoted GPS offsets are not universal."]}, {"q": "Using the explicitly supplied extension Δrate/rate≈gΔh/c², compare stationary clocks separated by 200 m near Earth over one day. Use g=9.80, c=3.00×10⁸ and 86400 s/day.", "points": ["Fractional gain=1960/(9.00×10¹⁶)=2.178×10⁻¹⁴.", "Daily gain≈1.882×10⁻⁹ s.", "Upper clock gains about 1.88 ns.", "This uses weak-field and small-height approximations with stationary clocks."]}], "bank": [{"q": "Higher stationary weak-field clock generally runs…", "o": ["faster than lower comparison clock", "slower always", "without any gravity"], "a": 0, "explain": "Higher gravitational potential gives an upper-clock gain."}, {"q": "GPS speed contribution tends to…", "o": ["oppose gravitational gain", "have the same sign always", "vanish by definition"], "a": 0, "explain": "Moving satellite clock has an SR slowing contribution."}, {"q": "Upward gravitational light transfer produces…", "o": ["redshift at higher receiver", "unchanged frequency necessarily", "local c greater than c"], "a": 0, "explain": "Frequency decreases in the stated receiver comparison."}, {"q": "cΔt represents…", "o": ["a range-equivalent timing error", "every exact position error", "a clock invariant mass"], "a": 0, "explain": "Navigation geometry and receiver clock also matter."}, {"q": "Supplied +45 and −7 offsets sum to…", "o": ["+38", "+52", "−52"], "a": 0, "explain": "Combine signed quantities."}, {"q": "One orbit correction pair is…", "o": ["orbit-dependent", "universal for all satellites", "independent of speed"], "a": 0, "explain": "Height and orbital speed change the contributions."}], "transfer": [["Different flight paths", "Compare a stationary elevated clock with a moving aircraft clock. The elevated stationary comparison isolates gravity; the aircraft adds speed and path dependence."], ["Signal direction test", "Reverse the upward photon diagram: a lower stationary receiver measures a higher frequency for downward light. State receiver and emitter rather than assigning an unqualified shift."], ["A practical system", "GPS models include further operational corrections beyond this lesson. The two-effect ledger explains why relativity matters without claiming to be a complete navigation algorithm."]], "summary": "Combine signed satellite clock effects and explain gravitational redshift with clearly defined endpoints.", "mode": null}, {"id": "general-relativity-focus-3", "parent": "general-relativity", "title": "General-relativity evidence: lenses, black holes and gravitational waves", "shortTitle": "Evidence & cosmic scenarios", "subtitle": "Interpret lensing, horizon and gravitational-wave evidence while distinguishing observations, diagrams and supplied extension calculations.", "rows": [{"chapter": 0, "title": "Predictions require evidence", "body": "A convincing explanation links an observation to a specific model prediction and acknowledges competing effects or uncertainty. Beautiful space pictures alone do not demonstrate every detail of a physical theory.", "fig": "lens", "type": "learn"}, {"chapter": 0, "title": "Light paths in curved spacetime", "body": "Light follows paths determined by spacetime geometry. A ray passing a gravitating mass can change apparent direction relative to a distant observer. This does not require the photon to have nonzero invariant mass.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "A lens geometry", "body": "A background source, intervening gravitating mass and observer form a gravitational lens arrangement. Different light paths can produce multiple images, arcs or changes in apparent brightness, depending on alignment.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Images are not duplicate sources", "body": "Several apparent images can originate from one physical background object. Similar spectra or correlated variability with time delays can help identify the common source. The intervening lens need not emit the source's light.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Time delay between images", "body": "Different lens paths can have different travel times. A variable source may be observed changing in separate images at different times. A delayed appearance does not require the source to repeat the same event independently.", "fig": "horizon", "type": "learn"}, {"chapter": 0, "title": "Alignment changes the pattern", "body": "Nearly symmetric alignment can form a ring-like image in an idealised model. Less symmetric arrangements yield arcs or separated images. A schematic two-ray diagram cannot predict every observed lens shape.", "fig": null, "type": "learn"}, {"chapter": 0, "title": "Black-hole meaning", "body": "A black hole contains a region from which outward signals cannot escape to distant observers. The event horizon is a causal boundary. It is not an ordinary solid surface that spacecraft could stand on.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Horizon and singularity are different", "body": "The horizon bounds the no-escape region; it is not the same object as the central singularity of an ideal model. Classical singularity descriptions indicate limits requiring care rather than a directly photographed point.", "fig": "waves", "type": "learn"}, {"chapter": 1, "title": "Outside matter can emit", "body": "Hot gas outside the horizon can radiate and be observed. Seeing surrounding emission does not mean light has escaped from inside the horizon. Separate emitting material from the causal boundary.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Mass and scale", "body": "More massive non-rotating black holes have larger horizon radius in the simple supplied extension model. Real rotating black holes require a different detailed geometry. Do not treat a schematic picture as a scale measurement.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Not a cosmic vacuum cleaner", "body": "At large distance, a gravitating body's influence depends on mass and distance. Replacing a star by an equal-mass compact object does not automatically pull every distant orbit inward. Close tidal conditions and horizon proximity are different concerns.", "fig": "lens", "type": "learn"}, {"chapter": 1, "title": "Tidal conditions vary", "body": "Strong field gradients can stretch and compress extended objects. Horizon crossing and damaging tidal forces are different concepts; their relationship depends on black-hole mass and the object's path.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Gravitational waves", "body": "Accelerating mass arrangements with a changing appropriate asymmetry can produce propagating spacetime disturbances. Compact-object binaries are important sources. A stationary isolated spherical mass does not emit a continuous wave merely because it has gravity.", "fig": null, "type": "learn"}, {"chapter": 1, "title": "Detector measures strain", "body": "An interferometer detects tiny changing relative arm lengths, expressed as dimensionless strain. Laser light is a measurement tool; the gravitational wave is not a sound wave or electromagnetic light wave.", "fig": null, "type": "learn"}, {"chapter": 2, "title": "Worked: lens interpretation", "body": "A telescope observes two similar spectra in separate images around an intervening mass. A gravitational lens is a candidate explanation: one source's light follows multiple paths. Similarity alone requires further corroboration, not automatic certainty.", "fig": "horizon", "type": "worked"}, {"chapter": 2, "title": "Worked: a repeated brightness variation", "body": "Suppose one lens image brightens and another follows three days later with the same pattern. A three-day path delay is consistent with one variable source seen by different paths. It is not evidence for superluminal messaging between images.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a horizon statement", "body": "A diagram labels an orange emitting ring outside a dark central region. The ring can represent external hot matter. Do not label that radiation as light emerging from inside the event horizon.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: a distant-orbit claim", "body": "If a spherical star could hypothetically become a black hole without changing mass, a distant orbit would not change simply because the object gained a horizon, under the same ideal exterior gravitational conditions. Real collapse may eject mass and alter conditions.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: supplied horizon-radius extension", "body": "For a non-rotating model only, take r_s=2GM/c², supplied G=6.67×10⁻¹¹, M=2.00×10³⁰ kg and c=3.00×10⁸. This quantitative formula is explicitly extension rather than an assumed core derivation.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: calculate the extension scale", "body": "r_s=2×6.67×10⁻¹¹×2.00×10³⁰/(9.00×10¹⁶)≈2964 m≈2.96 km. The radius scales linearly with mass in this non-rotating supplied model.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: supplied detector strain", "body": "Define a simplified extension strain model h=ΔL/L. For L=4000 m and h=1.00×10⁻²¹, ΔL=hL=4.00×10⁻¹⁸ m. This is a supplied scale calculation, not a full interferometer-response equation.", "fig": "waves", "type": "worked"}, {"chapter": 2, "title": "Worked: why a chirp rises", "body": "As a compact binary loses orbital energy through gravitational waves, its orbit can shrink and orbital frequency rise. The detected waveform's frequency and amplitude can rise toward merger. A drawn chirp is illustrative, not a measured event.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: reject a sound analogy", "body": "A gravitational wave can propagate through vacuum. An audible playback maps the detector signal into sound for human listening; that playback does not mean the cosmic wave travelled as air-pressure oscillations.", "fig": null, "type": "worked"}, {"chapter": 2, "title": "Worked: assess corroboration", "body": "A candidate signal observed consistently in multiple separated detectors is more convincing than an isolated instrumental fluctuation. Compare arrival timing, waveform consistency and noise analysis before claiming a source identification.", "fig": null, "type": "worked"}], "guides": [{"q": "Supplied h=2×10⁻²¹ and L=3000 m. Find ΔL.", "value": 6e-18, "unit": "m", "why": "ΔL=hL=6×10⁻¹⁸ m; supplied extension model.", "tolerance": 1e-20}, {"q": "Supplied non-rotating radius 3 km at mass M. Radius at 4M?", "value": 12, "unit": "km", "why": "r_s is proportional to M in the supplied extension model.", "tolerance": 0.025}], "practice": [{"q": "A lens produces two correlated source-light curves with a five-day delay. Explain the physical interpretation and why it does not imply signals crossed between the images faster than light.", "points": ["One source can be seen along different bent paths.", "Different paths have different travel times.", "The two images show the same source event at different reception times.", "No message between apparent images is required."]}, {"q": "Explain the difference between an event horizon, external emitting gas and a gravitational-wave detector signal.", "points": ["Horizon is a causal no-escape boundary.", "External hot material can emit observable radiation.", "Gravitational waves are spacetime disturbances.", "Interferometers measure tiny relative-length changes rather than light escaping the horizon."]}], "tasks": [{"q": "A supplied non-rotating horizon model has r_s=2GM/c². For M=6.00×10³⁰ kg, G=6.67×10⁻¹¹ and c=3.00×10⁸, find r_s and name a limitation.", "points": ["r_s=2×6.67×10⁻¹¹×6.00×10³⁰/(9.00×10¹⁶).", "r_s≈8893 m=8.89 km.", "Radius is a causal-boundary scale, not an ordinary solid surface.", "The supplied formula assumes a non-rotating model; quantitative calculation is extension."]}, {"q": "Using supplied strain h=ΔL/L, a 2000 m detector arm has h=3.00×10⁻²¹. Find ΔL and explain why an audio playback is not the original propagation medium.", "points": ["ΔL=hL.", "ΔL=6.00×10⁻¹⁸ m.", "The cosmic signal is a spacetime disturbance propagating in vacuum.", "Sound playback is a mapped detector signal for listening, not cosmic air-pressure propagation."]}], "bank": [{"q": "Multiple lens images can represent…", "o": ["one source via different paths", "mandatory duplicate galaxies", "photons with nonzero invariant mass"], "a": 0, "explain": "Curved light paths change apparent direction."}, {"q": "The event horizon is…", "o": ["a causal boundary", "a solid emitting surface", "identical to the singularity"], "a": 0, "explain": "Inside it outgoing signals cannot escape to distant observers."}, {"q": "Observed hot material may be…", "o": ["outside the horizon", "necessarily inside it", "proof there is no horizon"], "a": 0, "explain": "External gas emits observable radiation."}, {"q": "Gravitational waves are…", "o": ["spacetime disturbances", "sound in space air", "identical to laser light"], "a": 0, "explain": "Interferometers use light to measure a gravitational signal."}, {"q": "A rising chirp can indicate…", "o": ["a shrinking inspiral", "a stationary spherical source necessarily", "local c increasing"], "a": 0, "explain": "Energy loss can shrink orbit and raise frequency."}, {"q": "Multiple detectors help…", "o": ["reject local instrumental noise", "make all uncertainty vanish", "create a cosmic wave"], "a": 0, "explain": "Timing and waveform consistency strengthen evidence."}], "transfer": [["A source identification claim", "Explain which feature supports lensing, which supports a merger interpretation and what extra information would strengthen each. Avoid using a single image to establish unrelated predictions."], ["A diagram literacy check", "Locate observer, background source and lens mass. Then distinguish horizon boundary from external emitting matter on the black-hole figure. Labels should support the explanation, not substitute for it."], ["Quantitative extensions", "The supplied horizon-radius and strain equations illustrate scales. Keep their assumptions visible and do not imply a core student must derive advanced general-relativity field equations."]], "summary": "Interpret lensing, horizon and gravitational-wave evidence while distinguishing observations, diagrams and supplied extension calculations.", "mode": null}];

for(const s of specs){
 const pages=s.rows.map(r=>({chapter:r.chapter,title:r.title,type:r.type,html:'<div class="pp-page">'+P(esc(r.body))+(r.fig?figs[r.fig]():'')+'</div>'}));
 s.guides.forEach((g,i)=>pages.push({chapter:3,title:'Guided calculation '+(i+1)+': '+g.q,type:'interactive',html:'<div class="pp-page">'+P('Identify the frame, supplied model and units before calculating. '+esc(g.q))+number(s.id+'-guided-'+i,g.q,g.value,g.unit,g.why,g.tolerance)+'</div>'}));
 const b=s.bank[0];pages.push({chapter:3,title:'Model choice: explain the reasoning',type:'interactive',html:'<div class="pp-page">'+check(s.id+'-model',b.q,b.o,b.a,b.o.map((_,i)=>i===b.a?b.explain:'Reconsider the frame and the quantity being measured. '+b.explain))+'</div>'});
 s.practice.forEach((q,i)=>pages.push({chapter:3,title:'Independent original exam-style scenario '+(i+1),type:'practice',html:'<div class="pp-page">'+P('<b>'+q.points.length+' marks.</b> '+esc(q.q))+paper('Your labelled diagram, model, working and interpretation')+reveal('Explain how to solve and award the marks',marking(q.points))+'</div>'}));
 s.transfer.forEach(t=>pages.push({chapter:3,title:t[0],type:'learn',html:'<div class="pp-page">'+P(esc(t[1]))+'</div>'}));
 if(s.mode)pages.push({chapter:3,title:'Explore speed: predict, adjust and explain',type:'interactive',html:'<div class="pp-page">'+explore(s.mode)+'</div>'});
 C.register({id:s.id,parent:s.parent,title:s.title,shortTitle:s.shortTitle,subtitle:s.subtitle,pages,bank:s.bank,practice:s.practice,chapters:[['Recognise','Identify events, frames and physical quantities'],['Build','Connect measurements, assumptions and models'],['Solve','Explained original exam-style scenarios'],['Practise','Guided calculation, independent transfer and mastery']],constants:'Use supplied c=3.00×10⁸ m/s. Other constants and non-core quantitative extension models are supplied explicitly. All worked questions are original exam-style teaching examples.',summary:s.summary,focus:{question:s.practice[0].q,points:s.practice[0].points,claim:s.bank[0].explain},wire:wireRel});
}
})();
